import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface PlanetConfig {
  name: string;
  color: string;
  radius: number;
  distance: number; // AU
  speed: number; // Relative orbital speed
  description: string;
  type: 'star' | 'planet';
  hasRing?: boolean;
}

export interface Star {
  x: number;
  y: number;
  size: number;
  opacity: number;
}

export interface SimulationState {
  scale: number;
  speedMultiplier: number;
  offsetX: number;
  offsetY: number;
}

export interface PlanetRuntimeState {
  name: string;
  angle: number;
  visualDistance: number;
}

import { PlanetConfig, Star } from './types';

export const PLANETS: PlanetConfig[] = [
  { name: "Matahari", color: "#FFD700", radius: 25, distance: 0, speed: 0, description: "Bintang pusat tata surya.", type: "star" },
  { name: "Merkurius", color: "#A9A9A9", radius: 4, distance: 0.39, speed: 4.1, description: "Planet terkecil & terdekat.", type: "planet" },
  { name: "Venus", color: "#E3BB76", radius: 7, distance: 0.72, speed: 1.6, description: "Planet terpanas.", type: "planet" },
  { name: "Bumi", color: "#4B90D6", radius: 7.5, distance: 1.00, speed: 1.0, description: "Rumah kita (dan Cikampek).", type: "planet" },
  { name: "Mars", color: "#D14A28", radius: 5, distance: 1.52, speed: 0.53, description: "Planet Merah.", type: "planet" },
  { name: "Jupiter", color: "#D9A066", radius: 18, distance: 5.20, speed: 0.084, description: "Raksasa gas terbesar.", type: "planet" },
  { name: "Saturnus", color: "#EDD59E", radius: 15, distance: 9.58, speed: 0.034, description: "Memiliki cincin indah.", type: "planet", hasRing: true },
  { name: "Uranus", color: "#93B8BE", radius: 10, distance: 19.22, speed: 0.011, description: "Planet es raksasa.", type: "planet" },
  { name: "Neptunus", color: "#3E54E8", radius: 10, distance: 30.05, speed: 0.006, description: "Planet terjauh & berangin.", type: "planet" }
];

export const generateStars = (count: number): Star[] => {
  const stars: Star[] = [];
  for(let i=0; i<count; i++) {
    stars.push({
      x: Math.random() * 3000 - 1500,
      y: Math.random() * 3000 - 1500,
      size: Math.random() * 1.5,
      opacity: Math.random()
    });
  }
  return stars;
};

