export const generateStars = (count: number): Star[] => {
  const stars: Star[] = [];
  for(let i=0; i<count; i++) {
    stars.push({
      x: Math.random() * 4000 - 2000,
      y: Math.random() * 4000 - 2000,
      size: Math.random() * 2 + 0.5,
      opacity: Math.random() * 0.8 + 0.2
    });
  }
  return stars;
};

export const generateAsteroids = (count: number): Asteroid[] => {
  const asteroids: Asteroid[] = [];
  for(let i=0; i<count; i++) {
    // Belt between Mars (1.52) and Jupiter (5.20), typically 2.2 - 3.2 AU
    const minDist = 2.2;
    const maxDist = 3.2;
    const distance = Math.random() * (maxDist - minDist) + minDist;

    asteroids.push({
      angle: Math.random() * Math.PI * 2,
      distance: distance,
      speed: (1 / Math.sqrt(distance)) * 4, // Kepler's approximation
      size: Math.random() * 1.5 + 0.5,
      offset: Math.random() * 0.2
    });
  }
  return asteroids;
};

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { PLANETS, generateStars, generateAsteroids } from '../constants';
import { PlanetConfig, PlanetRuntimeState, Asteroid } from '../types';
import { Tooltip } from './Tooltip';
import { Controls } from './Controls';
import { SidePanel } from './SidePanel';

const AU_PIXELS = 100;

const SolarSystem: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [hoveredPlanet, setHoveredPlanet] = useState<PlanetConfig | null>(null);
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetConfig | null>(null); // For Side Panel
  const [following, setFollowing] = useState<string | null>(null); // Name of planet camera is locked to

  const [cursorPos, setCursorPos] = useState({ x: 0, y: 0 });
  const [uiSpeed, setUiSpeed] = useState(1);
  const [uiZoom, setUiZoom] = useState(0.5);
  const [isPlaying, setIsPlaying] = useState(true);
  const [simulationDate, setSimulationDate] = useState(Date.now());

  // Simulation State Refs (Mutable for loop performance)
  const simulationState = useRef({
    scale: 0.5,
    speedMultiplier: 1,
    offsetX: 0,
    offsetY: 0,
    isDragging: false,
    lastMouseX: 0,
    lastMouseY: 0,
    cameraTarget: { x: 0, y: 0 }, // Target position for smooth camera interpolation
  });

  const planetsRuntime = useRef<PlanetRuntimeState[]>(
    PLANETS.map(p => ({
      name: p.name,
      angle: Math.random() * Math.PI * 2,
      visualDistance: p.name === 'Matahari' ? 0 : (p.distance * AU_PIXELS),
      trail: [],
      // Initialize moons with random angles if they exist
      moons: p.moons ? p.moons.map(() => ({ angle: Math.random() * Math.PI * 2 })) : []
    }))
  );

  // Static Data
  const stars = useMemo(() => generateStars(800), []);
  const asteroids = useMemo(() => generateAsteroids(400), []);

  // Sync UI with Refs
  useEffect(() => { simulationState.current.speedMultiplier = uiSpeed; }, [uiSpeed]);
  useEffect(() => { simulationState.current.scale = uiZoom; }, [uiZoom]);

  // Main Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); // Optimize alpha
    if (!ctx) return;

    let animationFrameId: number;

    const render = () => {
      // 1. Resize Handling
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }

      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      const { scale, offsetX, offsetY, speedMultiplier } = simulationState.current;

      // 2. Physics & Logic Update
      if (isPlaying) {
        // Update Time
        // 1 sec real time = approx 60 days at speed 1.0 (arbitrary scale for feel)
        setSimulationDate(d => d + (speedMultiplier * 86400 * 1000 * 0.1));

        // Update Planets
        planetsRuntime.current.forEach((rtPlanet, index) => {
          const config = PLANETS[index];
          if (config.type === 'planet') {
            rtPlanet.angle += (config.speed * 0.005) * speedMultiplier;

            // Update Trail
            const px = Math.cos(rtPlanet.angle) * rtPlanet.visualDistance;
            const py = Math.sin(rtPlanet.angle) * rtPlanet.visualDistance;

            // Add point to trail every frame but limit length
            if (rtPlanet.trail.length > 50) rtPlanet.trail.shift();
            rtPlanet.trail.push({ x: px, y: py });

            // Update Moons
            if (config.moons && rtPlanet.moons) {
              config.moons.forEach((moon, mIndex) => {
                // Moon speed scaling: faster than planets usually, adjusted for visual pleasantness
                rtPlanet.moons[mIndex].angle += (moon.speed * 0.02) * speedMultiplier;
              });
            }
          }
        });

        // Update Asteroids
        asteroids.forEach(ast => {
          ast.angle += (ast.speed * 0.005) * speedMultiplier;
        });
      }

      // 3. Camera "Follow" Logic
      let currentOffsetX = offsetX;
      let currentOffsetY = offsetY;

      if (following) {
        const targetPlanet = planetsRuntime.current.find(p => p.name === following);
        if (targetPlanet) {
            // Calculate where the planet is relative to center (0,0)
            const pX = Math.cos(targetPlanet.angle) * targetPlanet.visualDistance;
            const pY = Math.sin(targetPlanet.angle) * targetPlanet.visualDistance;

            // To center the planet, the offset must be the inverse of its position
            simulationState.current.offsetX = -pX;
            simulationState.current.offsetY = -pY;
            currentOffsetX = -pX;
            currentOffsetY = -pY;
        }
      }

      // 4. Rendering
      ctx.fillStyle = '#050505'; // Deep space
      ctx.fillRect(0, 0, width, height);

      // Radial Gradient Background (Subtle center glow)
      const bgGrad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, width);
      bgGrad.addColorStop(0, '#0a0a10');
      bgGrad.addColorStop(1, '#000000');
      ctx.fillStyle = bgGrad;
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(cx + currentOffsetX, cy + currentOffsetY);
      ctx.scale(scale, scale);

      // Draw Stars (Parallax)
      ctx.fillStyle = '#FFF';
      const parallaxScale = Math.max(0.1, 1/scale); 
      stars.forEach(star => {
        ctx.globalAlpha = star.opacity;
        ctx.beginPath();
        ctx.arc(star.x * parallaxScale, star.y * parallaxScale, star.size / scale, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // Draw Orbit Lines
      ctx.lineWidth = Math.max(0.5, 0.5 / scale);
      ctx.strokeStyle = '#222';
      planetsRuntime.current.forEach(p => {
        if (p.visualDistance > 0) {
          ctx.beginPath();
          ctx.arc(0, 0, p.visualDistance, 0, Math.PI * 2);
          ctx.stroke();
        }
      });

      // Draw Asteroids
      ctx.fillStyle = '#666';
      asteroids.forEach(ast => {
        const r = ast.distance * AU_PIXELS;
        const x = Math.cos(ast.angle) * r;
        const y = Math.sin(ast.angle) * r;

        ctx.beginPath();
        ctx.arc(x, y, (ast.size / scale), 0, Math.PI * 2);
        ctx.fill();
      });

      // Draw Sun (Glow + Body)
      const sunConfig = PLANETS[0];
      const sunGrad = ctx.createRadialGradient(0, 0, sunConfig.radius * 0.5, 0, 0, sunConfig.radius * 6);
      sunGrad.addColorStop(0, '#FFF');
      sunGrad.addColorStop(0.1, '#FFD700');
      sunGrad.addColorStop(0.2, 'rgba(255, 165, 0, 0.8)');
      sunGrad.addColorStop(0.5, 'rgba(255, 69, 0, 0.2)');
      sunGrad.addColorStop(1, 'rgba(0,0,0,0)');

      ctx.fillStyle = sunGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sunConfig.radius * 6, 0, Math.PI * 2);
      ctx.fill();

      // Draw Planets & Trails
      planetsRuntime.current.forEach((rtPlanet, index) => {
        const config = PLANETS[index];
        if (config.type !== 'planet') return;

        // Draw Trail
        if (rtPlanet.trail.length > 1) {
          ctx.beginPath();
          ctx.strokeStyle = config.color;
          ctx.lineWidth = Math.max(1, 2/scale);
          ctx.globalAlpha = 0.3;

          rtPlanet.trail.forEach((point, i) => {
            if (i === 0) ctx.moveTo(point.x, point.y);
            else ctx.lineTo(point.x, point.y);
          });
          ctx.stroke();
          ctx.globalAlpha = 1.0;
        }

        const x = Math.cos(rtPlanet.angle) * rtPlanet.visualDistance;
        const y = Math.sin(rtPlanet.angle) * rtPlanet.visualDistance;

        // Draw Rings
        if (config.hasRing) {
          ctx.beginPath();
          ctx.strokeStyle = 'rgba(200, 200, 200, 0.4)';
          ctx.lineWidth = Math.max(3, 4/scale);
          ctx.ellipse(x, y, config.radius * 2.5, config.radius * 0.8, rtPlanet.angle + Math.PI/4, 0, Math.PI * 2);
          ctx.stroke();
        }

        // Draw Planet Body (Pseudo-3D)
        const planetGrad = ctx.createRadialGradient(x - config.radius/3, y - config.radius/3, config.radius/10, x, y, config.radius);
        planetGrad.addColorStop(0, lightenColor(config.color, 40));
        planetGrad.addColorStop(0.5, config.color);
        planetGrad.addColorStop(1, darkenColor(config.color, 40));

        ctx.fillStyle = planetGrad;
        ctx.beginPath();
        ctx.arc(x, y, config.radius, 0, Math.PI * 2);
        ctx.fill();

        // Draw Moons (LOD Culling: Only draw if zoomed in enough)
        if (config.moons && rtPlanet.moons && scale > 0.15) {
          config.moons.forEach((moon, mIndex) => {
            const mAngle = rtPlanet.moons[mIndex].angle;
            const mx = x + Math.cos(mAngle) * moon.distance;
            const my = y + Math.sin(mAngle) * moon.distance;

            ctx.fillStyle = moon.color;
            ctx.beginPath();
            // Moons are small, ensure at least some visibility
            ctx.arc(mx, my, moon.radius, 0, Math.PI * 2);
            ctx.fill();
          });
        }

        // Selection Highlight
        if (selectedPlanet?.name === config.name || hoveredPlanet?.name === config.name) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 2 / scale;
          ctx.beginPath();
          ctx.arc(x, y, config.radius + (4/scale), 0, Math.PI * 2);
          ctx.stroke();
        }

        // Labels
        if (scale < 0.25 || selectedPlanet?.name === config.name) {
          ctx.fillStyle = '#FFF';
          ctx.font = `bold ${12/scale}px "Segoe UI", sans-serif`;
          ctx.textAlign = 'center';
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 4;
          ctx.fillText(config.name, x, y - (config.radius + 10/scale));
          ctx.shadowBlur = 0;
        }
      });

      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animationFrameId);
  }, [stars, asteroids, isPlaying, following, selectedPlanet, hoveredPlanet]);

  // Helper: Color manipulation for gradients
  const lightenColor = (col: string, amt: number) => col; 
  const darkenColor = (col: string, amt: number) => 'black';

  // Interaction Handlers
  const handleWheel = (e: React.WheelEvent) => {
    const scale = simulationState.current.scale;
    const zoomSensitivity = 0.001 * scale; 
    let newScale = scale - e.deltaY * zoomSensitivity;
    newScale = Math.max(0.01, Math.min(newScale, 5));
    simulationState.current.scale = newScale;
    setUiZoom(newScale);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    simulationState.current.isDragging = true;
    simulationState.current.lastMouseX = e.clientX;
    simulationState.current.lastMouseY = e.clientY;
    if (following) setFollowing(null);
  };

  const handleMouseUp = () => {
    simulationState.current.isDragging = false;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (simulationState.current.isDragging) {
      const dx = e.clientX - simulationState.current.lastMouseX;
      const dy = e.clientY - simulationState.current.lastMouseY;
      simulationState.current.offsetX += dx;
      simulationState.current.offsetY += dy;
      simulationState.current.lastMouseX = e.clientX;
      simulationState.current.lastMouseY = e.clientY;
      setHoveredPlanet(null);
      return;
    }

    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    const width = canvas.width; 
    const height = canvas.height;
    const cx = width / 2;
    const cy = height / 2;
    const { scale, offsetX, offsetY } = simulationState.current;

    let found: PlanetConfig | null = null;

    for (let i = 0; i < planetsRuntime.current.length; i++) {
      const rtP = planetsRuntime.current[i];
      const config = PLANETS[i];

      let screenX, screenY;
      if (config.type === 'star') {
        screenX = cx + offsetX;
        screenY = cy + offsetY;
      } else {
        screenX = cx + offsetX + Math.cos(rtP.angle) * rtP.visualDistance * scale;
        screenY = cy + offsetY + Math.sin(rtP.angle) * rtP.visualDistance * scale;
      }

      const hitRadius = Math.max(config.radius * scale, 10);
      const dist = Math.hypot(mouseX - screenX, mouseY - screenY);

      if (dist < hitRadius) {
        found = config;
        break;
      }
    }

    setHoveredPlanet(found);
    if (found) {
      setCursorPos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleClick = () => {
    if (hoveredPlanet) {
      setSelectedPlanet(hoveredPlanet);
      setFollowing(hoveredPlanet.name);
    }
  };

  const handleSelectPlanet = (p: PlanetConfig) => {
    setSelectedPlanet(p);
    setFollowing(p.name);
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      <Controls 
        speed={uiSpeed} setSpeed={setUiSpeed} 
        zoom={uiZoom} setZoom={setUiZoom} 
        isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}
        date={simulationDate}
        onSelectPlanet={handleSelectPlanet}
        following={following}
      />

      <canvas
        ref={canvasRef}
        className={`block w-full h-full ${simulationState.current.isDragging ? 'cursor-grabbing' : hoveredPlanet ? 'cursor-pointer' : 'cursor-default'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onMouseMove={handleMouseMove}
        onClick={handleClick}
      />

      {!selectedPlanet && (
        <Tooltip x={cursorPos.x} y={cursorPos.y} planet={hoveredPlanet} />
      )}

      <SidePanel 
        planet={selectedPlanet} 
        onClose={() => setSelectedPlanet(null)} 
        onFollow={(name) => setFollowing(name === following ? null : name)}
        isFollowing={!!(selectedPlanet && following === selectedPlanet.name)}
      />
    </div>
  );
};

