import React, { useRef, useEffect, useState, useMemo } from 'react';
import { PLANETS, generateStars, generateAsteroids } from '../constants';
import { PlanetConfig, PlanetRuntimeState, MoonConfig } from '../types';
import { Tooltip } from './Tooltip';
import { Controls } from './Controls';
import { SidePanel } from './SidePanel';

// Scale Factors
const AU_PIXELS = 120; // Scale Distance
const PLANET_SCALE_FACTOR = 1; // Base scale for planet sizes

const SolarSystem: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [hoveredPlanet, setHoveredPlanet] = useState<PlanetConfig | MoonConfig | null>(null);
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetConfig | MoonConfig | null>(null); 
  const [following, setFollowing] = useState<string | null>(null); 

  const [cursorPos, setCursorPos] = useState({ x: 0, y: 0 });
  const [uiSpeed, setUiSpeed] = useState(1);
  const [uiZoom, setUiZoom] = useState(0.4); // Start zoomed out a bit more
  const [isPlaying, setIsPlaying] = useState(true);
  const [simulationDate, setSimulationDate] = useState(Date.now());

  // Simulation State
  const simulationState = useRef({
    scale: 0.4,
    speedMultiplier: 1,
    offsetX: 0,
    offsetY: 0,
    isDragging: false,
    lastMouseX: 0,
    lastMouseY: 0,
  });

  const planetsRuntime = useRef<PlanetRuntimeState[]>(
    PLANETS.map(p => ({
      name: p.name,
      angle: Math.random() * Math.PI * 2,
      visualX: 0,
      visualY: 0,
      trail: [],
      moons: p.moons ? p.moons.map(() => ({ angle: Math.random() * Math.PI * 2 })) : []
    }))
  );

  const stars = useMemo(() => generateStars(1000), []);
  const asteroids = useMemo(() => generateAsteroids(500), []);

  useEffect(() => { simulationState.current.speedMultiplier = uiSpeed; }, [uiSpeed]);
  useEffect(() => { simulationState.current.scale = uiZoom; }, [uiZoom]);

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    let animationFrameId: number;

    const render = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }

      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      const { scale, offsetX, offsetY, speedMultiplier } = simulationState.current;

      // --- PHYSICS UPDATE ---
      if (isPlaying) {
        setSimulationDate(d => d + (speedMultiplier * 86400 * 1000 * 0.1));

        planetsRuntime.current.forEach((rtPlanet, index) => {
          const config = PLANETS[index];
          if (config.type === 'planet') {
            // Kepler's Law approximation for speed
            rtPlanet.angle += (config.speed * 0.002) * speedMultiplier;

            // ELLIPTICAL ORBIT CALCULATION
            const a = config.distance * AU_PIXELS; // Semi-major axis
            const e = config.eccentricity;
            const b = a * Math.sqrt(1 - e*e); // Semi-minor axis
            const c = a * e; // Distance from center to focus (Sun)

            // Current position relative to Ellipse Center
            let ex = a * Math.cos(rtPlanet.angle);
            let ey = b * Math.sin(rtPlanet.angle);

            // Shift so Sun (focus) is at (0,0)
            rtPlanet.visualX = ex - c; 
            rtPlanet.visualY = ey;

            // Trail Logic
            if (rtPlanet.trail.length > 80) rtPlanet.trail.shift();
            if (Math.floor(Date.now() / 20) % 2 === 0) {
                rtPlanet.trail.push({ x: rtPlanet.visualX, y: rtPlanet.visualY });
            }

            // Update Moons
            if (config.moons && rtPlanet.moons) {
              config.moons.forEach((moon, mIndex) => {
                rtPlanet.moons[mIndex].angle += (moon.speed * 0.02) * speedMultiplier;
              });
            }
          }
        });

        asteroids.forEach(ast => {
            ast.angle += (ast.speed * 0.002) * speedMultiplier;
        });
      }

      // --- CAMERA UPDATE ---
      let currentOffsetX = offsetX;
      let currentOffsetY = offsetY;

      if (following) {
        const targetPlanet = planetsRuntime.current.find(p => p.name === following);
        if (targetPlanet) {
            simulationState.current.offsetX = -targetPlanet.visualX;
            simulationState.current.offsetY = -targetPlanet.visualY;
            currentOffsetX = -targetPlanet.visualX;
            currentOffsetY = -targetPlanet.visualY;
        }
      }

      // --- DRAWING ---

      // 1. Background (Space)
      ctx.fillStyle = '#020205'; 
      ctx.fillRect(0, 0, width, height);

      const nebulaGrad = ctx.createRadialGradient(width/2, height/2, width * 0.2, width/2, height/2, width * 1.5);
      nebulaGrad.addColorStop(0, '#0a0b14');
      nebulaGrad.addColorStop(1, '#000000');
      ctx.fillStyle = nebulaGrad;
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(cx + currentOffsetX, cy + currentOffsetY);
      ctx.scale(scale, scale);

      // 2. Stars
      const parallaxScale = Math.max(0.1, 1/scale);
      stars.forEach(star => {
        ctx.globalAlpha = star.opacity;
        ctx.fillStyle = star.color;
        ctx.beginPath();
        ctx.arc(star.x * parallaxScale, star.y * parallaxScale, star.size / scale, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 3. Asteroid Belt
      ctx.fillStyle = '#555';
      asteroids.forEach(ast => {
        const r = ast.distance * AU_PIXELS;
        const x = Math.cos(ast.angle) * r;
        const y = Math.sin(ast.angle) * r;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.arc(x, y, (ast.size / scale), 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 4. Orbit Lines
      ctx.lineWidth = Math.max(0.5, 0.5 / scale);
      ctx.strokeStyle = '#333';

      // Fix: Changed 'rtP' to '_' to ignore unused parameter
      planetsRuntime.current.forEach((_, i) => {
          const config = PLANETS[i];
          if (config.type === 'planet') {
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const b = a * Math.sqrt(1 - e*e);
            const c = a * e;
            ctx.beginPath();
            ctx.ellipse(-c, 0, a, b, 0, 0, Math.PI * 2);
            ctx.stroke();
          }
      });

      // 5. Sun
      const sun = PLANETS[0];
      const coronaGrad = ctx.createRadialGradient(0, 0, sun.radius, 0, 0, sun.radius * 4);
      coronaGrad.addColorStop(0, 'rgba(255, 200, 0, 0.4)');
      coronaGrad.addColorStop(0.5, 'rgba(255, 100, 0, 0.1)');
      coronaGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = coronaGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius * 4, 0, Math.PI * 2);
      ctx.fill();

      const sunBodyGrad = ctx.createRadialGradient(0, 0, sun.radius * 0.2, 0, 0, sun.radius);
      sunBodyGrad.addColorStop(0, '#FFF');
      sunBodyGrad.addColorStop(0.4, '#FDB813');
      sunBodyGrad.addColorStop(1, '#FF8C00');
      ctx.fillStyle = sunBodyGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius, 0, Math.PI * 2);
      ctx.fill();

      // 6. Planets & Moons
      planetsRuntime.current.forEach((rtPlanet, index) => {
        const config = PLANETS[index];
        if (config.type !== 'planet') return;

        if (rtPlanet.trail.length > 1) {
          ctx.beginPath();
          ctx.strokeStyle = config.color;
          ctx.lineWidth = Math.max(1, 1/scale);
          ctx.globalAlpha = 0.3;
          rtPlanet.trail.forEach((point, i) => {
            if (i === 0) ctx.moveTo(point.x, point.y);
            else ctx.lineTo(point.x, point.y);
          });
          ctx.stroke();
          ctx.globalAlpha = 1.0;
        }

        const x = rtPlanet.visualX;
        const y = rtPlanet.visualY;
        const radius = config.radius * PLANET_SCALE_FACTOR;

        ctx.save();
        ctx.translate(x, y);

        if (config.name === 'Bumi' || config.name === 'Venus') {
            const atmoGrad = ctx.createRadialGradient(0, 0, radius, 0, 0, radius * 1.3);
            atmoGrad.addColorStop(0, (config.colors[2] || config.color) + '88');
            atmoGrad.addColorStop(1, 'rgba(0,0,0,0)');
            ctx.fillStyle = atmoGrad;
            ctx.beginPath();
            ctx.arc(0, 0, radius * 1.3, 0, Math.PI * 2);
            ctx.fill();
        }

        // Fix: Removed unused surfGrad variable
        if (config.colors.length > 2) {
             const angle = Math.PI / 4;
             const planetCtx = ctx.createLinearGradient(
                 -radius * Math.cos(angle), -radius * Math.sin(angle),
                 radius * Math.cos(angle), radius * Math.sin(angle)
             );
             config.colors.forEach((col, idx) => {
                 planetCtx.addColorStop(idx / (config.colors.length - 1), col);
             });
             ctx.fillStyle = planetCtx;
        } else {
             ctx.fillStyle = config.color;
        }

        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();

        if (config.hasRing) {
             ctx.save();
             ctx.rotate(Math.PI / 6);
             ctx.beginPath();
             ctx.strokeStyle = '#CDBA96';
             ctx.lineWidth = radius * 0.8;
             ctx.globalAlpha = 0.7;
             ctx.ellipse(0, 0, radius * 2.2, radius * 0.6, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.beginPath();
             ctx.strokeStyle = '#000';
             ctx.lineWidth = radius * 0.1;
             ctx.globalAlpha = 0.5;
             ctx.ellipse(0, 0, radius * 1.8, radius * 0.5, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.restore();
        }

        const angleToSun = Math.atan2(-y, -x);
        ctx.rotate(angleToSun);

        ctx.beginPath();
        ctx.fillStyle = 'rgba(0,0,0,0.75)';
        ctx.arc(0, 0, radius, Math.PI / 2, -Math.PI / 2); 
        ctx.fill();

        const shadowGrad = ctx.createLinearGradient(-radius/2, 0, radius/2, 0);
        shadowGrad.addColorStop(0, 'rgba(0,0,0,0.8)');
        shadowGrad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = shadowGrad;
        ctx.fillRect(-radius/2, -radius, radius, radius*2);

        ctx.restore();

        if (config.moons && rtPlanet.moons && scale > 0.15) {
          config.moons.forEach((moon, mIndex) => {
            const mAngle = rtPlanet.moons[mIndex].angle;
            const mx = x + Math.cos(mAngle) * moon.distance;
            const my = y + Math.sin(mAngle) * moon.distance;

            ctx.fillStyle = moon.color;
            ctx.beginPath();
            ctx.arc(mx, my, moon.radius, 0, Math.PI * 2);
            ctx.fill();

            const moonAngleToSun = Math.atan2(-my, -mx);
            ctx.save();
            ctx.translate(mx, my);
            ctx.rotate(moonAngleToSun);
            ctx.fillStyle = 'rgba(0,0,0,0.8)';
            ctx.beginPath();
            ctx.arc(0, 0, moon.radius, Math.PI/2, -Math.PI/2);
            ctx.fill();
            ctx.restore();

            if (selectedPlanet?.name === moon.name || hoveredPlanet?.name === moon.name) {
                ctx.strokeStyle = 'white';
                ctx.lineWidth = 1 / scale;
                ctx.beginPath();
                ctx.arc(mx, my, moon.radius + (2/scale), 0, Math.PI * 2);
                ctx.stroke();
            }
          });
        }

        if (selectedPlanet?.name === config.name || hoveredPlanet?.name === config.name) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 2 / scale;
          ctx.beginPath();
          ctx.arc(x, y, radius + (4/scale), 0, Math.PI * 2);
          ctx.stroke();
        }

        if (scale < 0.25 || selectedPlanet?.name === config.name) {
          ctx.fillStyle = '#EEE';
          ctx.font = `bold ${12/scale}px "Segoe UI", sans-serif`;
          ctx.textAlign = 'center';
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 4;
          ctx.fillText(config.name, x, y - (radius + 12/scale));
          ctx.shadowBlur = 0;
        }
      });

      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animationFrameId);
  }, [stars, asteroids, isPlaying, following, selectedPlanet, hoveredPlanet]);

  const handleWheel = (e: React.WheelEvent) => {
    const scale = simulationState.current.scale;
    const zoomSensitivity = 0.001 * scale; 
    let newScale = scale - e.deltaY * zoomSensitivity;
    newScale = Math.max(0.01, Math.min(newScale, 5));
    simulationState.current.scale = newScale;
    setUiZoom(newScale);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    simulationState.current.isDragging = true;
    simulationState.current.lastMouseX = e.clientX;
    simulationState.current.lastMouseY = e.clientY;
    if (following) setFollowing(null);
  };

  const handleMouseUp = () => {
    simulationState.current.isDragging = false;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (simulationState.current.isDragging) {
      const dx = e.clientX - simulationState.current.lastMouseX;
      const dy = e.clientY - simulationState.current.lastMouseY;
      simulationState.current.offsetX += dx;
      simulationState.current.offsetY += dy;
      simulationState.current.lastMouseX = e.clientX;
      simulationState.current.lastMouseY = e.clientY;
      setHoveredPlanet(null);
      return;
    }

    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    const width = canvas.width; 
    const height = canvas.height;
    const cx = width / 2;
    const cy = height / 2;
    const { scale, offsetX, offsetY } = simulationState.current;

    let found: PlanetConfig | MoonConfig | null = null;

    for (let i = 0; i < planetsRuntime.current.length; i++) {
      const rtP = planetsRuntime.current[i];
      const config = PLANETS[i];

      let pX = rtP.visualX;
      let pY = rtP.visualY;
      if (config.type === 'star') { pX = 0; pY = 0; }

      const screenX = cx + offsetX + pX * scale;
      const screenY = cy + offsetY + pY * scale;

      // Check Moons first
      if (config.moons && rtP.moons && scale > 0.15) {
         for(let m=0; m<config.moons.length; m++) {
             const moon = config.moons[m];
             const rtMoon = rtP.moons[m];
             const mx = pX + Math.cos(rtMoon.angle) * moon.distance;
             const my = pY + Math.sin(rtMoon.angle) * moon.distance;

             const screenMX = cx + offsetX + mx * scale;
             const screenMY = cy + offsetY + my * scale;

             const mHitRadius = Math.max(moon.radius * scale, 6); 
             const mDist = Math.hypot(mouseX - screenMX, mouseY - screenMY);

             if (mDist < mHitRadius) {
                 // FIX: Use 'as const' to satisfy TypeScript strict literal types
                 found = { ...moon, type: 'moon' as const };
                 break;
             }
         }
      }

      if (found) break;

      const hitRadius = Math.max(config.radius * scale, 12);
      const dist = Math.hypot(mouseX - screenX, mouseY - screenY);

      if (dist < hitRadius) {
        found = config;
        break;
      }
    }

    setHoveredPlanet(found);
    if (found) {
      setCursorPos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleClick = () => {
    if (hoveredPlanet) {
      setSelectedPlanet(hoveredPlanet);
      if (hoveredPlanet.type !== 'moon') {
        setFollowing(hoveredPlanet.name);
      }
    }
  };

  const handleSelectPlanet = (p: PlanetConfig) => {
    setSelectedPlanet(p);
    setFollowing(p.name);
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      <Controls 
        speed={uiSpeed} setSpeed={setUiSpeed} 
        zoom={uiZoom} setZoom={setUiZoom} 
        isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}
        date={simulationDate}
        onSelectPlanet={handleSelectPlanet}
        following={following}
      />

      <canvas
        ref={canvasRef}
        className={`block w-full h-full ${simulationState.current.isDragging ? 'cursor-grabbing' : hoveredPlanet ? 'cursor-pointer' : 'cursor-default'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onMouseMove={handleMouseMove}
        onClick={handleClick}
      />

      {!selectedPlanet && (
        <Tooltip x={cursorPos.x} y={cursorPos.y} planet={hoveredPlanet} />
      )}

      <SidePanel 
        planet={selectedPlanet} 
        onClose={() => setSelectedPlanet(null)} 
        onFollow={(name) => setFollowing(name === following ? null : name)}
        isFollowing={!!(selectedPlanet && following === selectedPlanet.name)}
      />
    </div>
  );
};

export default SolarSystem;

export interface MoonConfig {
  name: string;
  radius: number;
  distance: number; // Pixels from planet center
  speed: number; // Orbital speed relative to simulation
  color: string;
  description: string;
  type?: 'moon';
}

export interface PlanetConfig {
  name: string;
  color: string; // Base color
  colors: string[]; // Array for gradients/textures
  radius: number;
  distance: number; // Semi-major axis in AU
  eccentricity: number; // 0 = circle, >0 = ellipse
  speed: number; // Orbital speed relative to simulation
  description: string;
  type: 'star' | 'planet' | 'dwarf' | 'comet';
  hasRing?: boolean;
  moons?: MoonConfig[]; 
  // Detailed stats
  diameter: string;
  temp: string;
  dayLength: string;
  yearLength: string;
  funFact: string;
}

export interface Star {
  x: number;
  y: number;
  size: number;
  opacity: number;
  color: string; // Star temperature color
}

export interface Asteroid {
  angle: number;
  distance: number; 
  speed: number;
  size: number;
  offset: number; 
}

export interface PlanetRuntimeState {
  name: string;
  angle: number; // Current orbital angle (Mean anomaly approx)
  visualX: number;
  visualY: number;
  trail: {x: number, y: number}[]; 
  moons: { angle: number }[]; 
}

export interface SimulationState {
  scale: number;
  speedMultiplier: number;
  offsetX: number;
  offsetY: number;
  isDragging: boolean;
  lastMouseX: number;
  lastMouseY: number;
  isPlaying: boolean;
  simulationDate: number; 
}

import React from 'react';
import { PlanetConfig } from '../types';
import { PLANETS } from '../constants';

interface ControlsProps {
  speed: number;
  setSpeed: (val: number) => void;
  zoom: number;
  setZoom: (val: number) => void;
  isPlaying: boolean;
  togglePlay: () => void;
  date: number;
  onSelectPlanet: (p: PlanetConfig) => void;
  following: string | null;
  showHabitableZone: boolean;
  setShowHabitableZone: (val: boolean) => void;
  showComets: boolean;
  setShowComets: (val: boolean) => void;
}

export const Controls: React.FC<ControlsProps> = ({ 
  speed, setSpeed, zoom, setZoom, 
  isPlaying, togglePlay, date, 
  onSelectPlanet, following,
  showHabitableZone, setShowHabitableZone,
  showComets, setShowComets
}) => {
  const formattedDate = new Date(date).toLocaleDateString('id-ID', {
    year: 'numeric', month: 'long', day: 'numeric'
  });

  return (
    <div className="absolute top-0 left-0 w-full h-full pointer-events-none p-4 flex flex-col justify-between">

      {/* Top Bar: Title & Simulation Date */}
      <div className="flex justify-between items-start pointer-events-auto">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-orange-500 drop-shadow-sm">
            Tata Surya Karim
          </h1>
          <div className="flex items-center gap-2 text-gray-400 text-xs mt-1">
            <span className="bg-white/10 px-2 py-0.5 rounded border border-white/5">Real Scale Orbit</span>
            <span>1 AU = 100px</span>
          </div>
        </div>

        <div className="flex flex-col items-end gap-2">
            <div className="bg-black/60 backdrop-blur-md border border-gray-700 rounded-lg px-4 py-2 text-right">
                <div className="text-[10px] text-gray-400 uppercase tracking-widest">Simulasi Waktu</div>
                <div className="text-lg font-mono font-bold text-blue-400">{formattedDate}</div>
            </div>

            <div className="bg-black/60 backdrop-blur-md border border-gray-700 rounded-lg p-2 flex flex-col gap-2">
               <label className="flex items-center gap-2 cursor-pointer group">
                  <div className={`w-3 h-3 rounded-full border border-green-500 ${showHabitableZone ? 'bg-green-500' : 'bg-transparent'} transition-colors`}></div>
                  <input type="checkbox" checked={showHabitableZone} onChange={e => setShowHabitableZone(e.target.checked)} className="hidden" />
                  <span className="text-[10px] text-gray-300 group-hover:text-white uppercase font-bold">Zona Laik Huni</span>
               </label>
               <label className="flex items-center gap-2 cursor-pointer group">
                  <div className={`w-3 h-3 rounded-full border border-cyan-400 ${showComets ? 'bg-cyan-400' : 'bg-transparent'} transition-colors`}></div>
                  <input type="checkbox" checked={showComets} onChange={e => setShowComets(e.target.checked)} className="hidden" />
                  <span className="text-[10px] text-gray-300 group-hover:text-white uppercase font-bold">Tampilkan Komet</span>
               </label>
            </div>
        </div>
      </div>

      {/* Bottom Bar: Controls & Planet Picker */}
      <div className="flex flex-col md:flex-row gap-4 items-end md:items-center justify-between pointer-events-auto">

        {/* Playback Controls */}
        <div className="bg-black/80 backdrop-blur-xl border border-white/10 p-3 rounded-2xl flex items-center gap-4 shadow-2xl">
          <button 
            onClick={togglePlay}
            className="w-10 h-10 rounded-full bg-white text-black flex items-center justify-center hover:bg-gray-200 transition-transform active:scale-95"
          >
            <i className={`fas ${isPlaying ? 'fa-pause' : 'fa-play ml-1'}`}></i>
          </button>

          <div className="flex flex-col w-32">
            <label className="text-[10px] text-gray-400 font-bold flex justify-between">
              <span>KECEPATAN</span>
              <span>{speed.toFixed(1)}x</span>
            </label>
            <input
              type="range" min="0" max="10" step="0.1" value={speed}
              onChange={(e) => setSpeed(parseFloat(e.target.value))}
              className="h-1 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-yellow-500 mt-1"
            />
          </div>

          <div className="w-px h-8 bg-white/20 mx-1"></div>

          <div className="flex flex-col w-32">
            <label className="text-[10px] text-gray-400 font-bold flex justify-between">
              <span>ZOOM</span>
              <span>{zoom.toFixed(2)}x</span>
            </label>
            <input
              type="range" min="0.05" max="4" step="0.01" value={zoom}
              onChange={(e) => setZoom(parseFloat(e.target.value))}
              className="h-1 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-blue-500 mt-1"
            />
          </div>
        </div>

        {/* Planet Quick Select */}
        <div className="flex gap-2 overflow-x-auto max-w-full pb-2 md:pb-0 scrollbar-hide">
          {PLANETS.map(p => (
            <button
              key={p.name}
              onClick={() => onSelectPlanet(p)}
              className={`
                px-3 py-2 rounded-lg border text-xs font-bold whitespace-nowrap transition-all flex items-center gap-2
                ${following === p.name 
                  ? 'bg-blue-600 border-blue-400 text-white shadow-[0_0_10px_rgba(59,130,246,0.5)]' 
                  : 'bg-black/60 border-gray-700 text-gray-300 hover:bg-white/10 hover:border-white/30'}
                ${p.type === 'comet' && !showComets ? 'hidden' : ''}
              `}
            >
              <span className="w-2 h-2 rounded-full" style={{backgroundColor: p.color}}></span>
              {p.name}
              {following === p.name && <i className="fas fa-video text-[10px]"></i>}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { PLANETS, generateStars, generateAsteroids } from '../constants';
import { PlanetConfig, PlanetRuntimeState, MoonConfig } from '../types';
import { Tooltip } from './Tooltip';
import { Controls } from './Controls';
import { SidePanel } from './SidePanel';

// Scale Factors
const AU_PIXELS = 120; // Scale Distance
const PLANET_SCALE_FACTOR = 1; // Base scale for planet sizes

const SolarSystem: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [hoveredPlanet, setHoveredPlanet] = useState<PlanetConfig | MoonConfig | null>(null);
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetConfig | MoonConfig | null>(null); 
  const [following, setFollowing] = useState<string | null>(null); 

  const [cursorPos, setCursorPos] = useState({ x: 0, y: 0 });
  const [uiSpeed, setUiSpeed] = useState(1);
  const [uiZoom, setUiZoom] = useState(0.4); // Start zoomed out a bit more
  const [isPlaying, setIsPlaying] = useState(true);
  const [simulationDate, setSimulationDate] = useState(Date.now());

  // New Visualization States
  const [showHabitableZone, setShowHabitableZone] = useState(false);
  const [showComets, setShowComets] = useState(true);

  // Simulation State
  const simulationState = useRef({
    scale: 0.4,
    speedMultiplier: 1,
    offsetX: 0,
    offsetY: 0,
    isDragging: false,
    lastMouseX: 0,
    lastMouseY: 0,
  });

  const planetsRuntime = useRef<PlanetRuntimeState[]>(
    PLANETS.map(p => ({
      name: p.name,
      angle: Math.random() * Math.PI * 2,
      visualX: 0,
      visualY: 0,
      trail: [],
      moons: p.moons ? p.moons.map(() => ({ angle: Math.random() * Math.PI * 2 })) : []
    }))
  );

  const stars = useMemo(() => generateStars(1000), []);
  const asteroids = useMemo(() => generateAsteroids(500), []);

  useEffect(() => { simulationState.current.speedMultiplier = uiSpeed; }, [uiSpeed]);
  useEffect(() => { simulationState.current.scale = uiZoom; }, [uiZoom]);

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    let animationFrameId: number;

    const render = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }

      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      const { scale, offsetX, offsetY, speedMultiplier } = simulationState.current;

      // --- PHYSICS UPDATE ---
      if (isPlaying) {
        setSimulationDate(d => d + (speedMultiplier * 86400 * 1000 * 0.1));

        planetsRuntime.current.forEach((rtPlanet, index) => {
          const config = PLANETS[index];
          // Physics for Planets, Dwarfs, and Comets
          if (config.type === 'planet' || config.type === 'dwarf' || config.type === 'comet') {

            // Variable speed based on Kepler's 2nd Law (faster near perihelion)
            // Calculate r (distance) for current angle to adjust speed
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const currentR = (a * (1 - e * e)) / (1 + e * Math.cos(rtPlanet.angle));
            const normalizedR = currentR / (a); 
            // Simplified viscosity: closer = faster.
            const keplerSpeed = config.speed * (1 / (normalizedR * normalizedR)); 

            rtPlanet.angle += (keplerSpeed * 0.002) * speedMultiplier;

            // ELLIPTICAL ORBIT CALCULATION
            const b = a * Math.sqrt(1 - e*e); // Semi-minor axis
            const c = a * e; // Distance from center to focus (Sun)

            // Current position relative to Ellipse Center
            let ex = a * Math.cos(rtPlanet.angle);
            let ey = b * Math.sin(rtPlanet.angle);

            // Shift so Sun (focus) is at (0,0)
            rtPlanet.visualX = ex - c; 
            rtPlanet.visualY = ey;

            // Trail Logic
            if (rtPlanet.trail.length > 80) rtPlanet.trail.shift();
            // Comets leave denser trails
            const trailFrequency = config.type === 'comet' ? 5 : 20;
            if (Math.floor(Date.now() / trailFrequency) % 2 === 0) {
                rtPlanet.trail.push({ x: rtPlanet.visualX, y: rtPlanet.visualY });
            }

            // Update Moons
            if (config.moons && rtPlanet.moons) {
              config.moons.forEach((moon, mIndex) => {
                rtPlanet.moons[mIndex].angle += (moon.speed * 0.02) * speedMultiplier;
              });
            }
          }
        });

        asteroids.forEach(ast => {
            ast.angle += (ast.speed * 0.002) * speedMultiplier;
        });
      }

      // --- CAMERA UPDATE ---
      let currentOffsetX = offsetX;
      let currentOffsetY = offsetY;

      if (following) {
        const targetPlanet = planetsRuntime.current.find(p => p.name === following);
        if (targetPlanet) {
            simulationState.current.offsetX = -targetPlanet.visualX;
            simulationState.current.offsetY = -targetPlanet.visualY;
            currentOffsetX = -targetPlanet.visualX;
            currentOffsetY = -targetPlanet.visualY;
        }
      }

      // --- DRAWING ---

      // 1. Background (Space)
      ctx.fillStyle = '#020205'; 
      ctx.fillRect(0, 0, width, height);

      const nebulaGrad = ctx.createRadialGradient(width/2, height/2, width * 0.2, width/2, height/2, width * 1.5);
      nebulaGrad.addColorStop(0, '#0a0b14');
      nebulaGrad.addColorStop(1, '#000000');
      ctx.fillStyle = nebulaGrad;
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(cx + currentOffsetX, cy + currentOffsetY);
      ctx.scale(scale, scale);

      // 2. Stars
      const parallaxScale = Math.max(0.1, 1/scale);
      stars.forEach(star => {
        ctx.globalAlpha = star.opacity;
        ctx.fillStyle = star.color;
        ctx.beginPath();
        ctx.arc(star.x * parallaxScale, star.y * parallaxScale, star.size / scale, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 3. Asteroid Belt
      ctx.fillStyle = '#555';
      asteroids.forEach(ast => {
        const r = ast.distance * AU_PIXELS;
        const x = Math.cos(ast.angle) * r;
        const y = Math.sin(ast.angle) * r;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.arc(x, y, (ast.size / scale), 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 4. Orbit Lines & Habitable Zone

      // Habitable Zone (Goldilocks Zone)
      if (showHabitableZone) {
          const hzInner = 0.95 * AU_PIXELS;
          const hzOuter = 1.37 * AU_PIXELS;
          ctx.beginPath();
          ctx.arc(0, 0, hzInner, 0, Math.PI * 2);
          ctx.arc(0, 0, hzOuter, 0, Math.PI * 2, true); // Create ring
          ctx.fillStyle = 'rgba(0, 255, 100, 0.1)';
          ctx.fill();
          ctx.strokeStyle = 'rgba(0, 255, 100, 0.2)';
          ctx.lineWidth = 1 / scale;
          ctx.stroke();
      }

      ctx.lineWidth = Math.max(0.5, 0.5 / scale);

      // Fix: Changed 'rtP' to '_' to ignore unused parameter
      planetsRuntime.current.forEach((_, i) => {
          const config = PLANETS[i];
          if (config.type === 'comet' && !showComets) return;

          if (config.type === 'planet' || config.type === 'dwarf' || config.type === 'comet') {
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const b = a * Math.sqrt(1 - e*e);
            const c = a * e;
            ctx.beginPath();
            ctx.strokeStyle = config.type === 'comet' ? 'rgba(255,255,255,0.1)' : (config.type === 'dwarf' ? '#555' : '#333');
            // Dashed line for comets/dwarfs
            if (config.type !== 'planet') ctx.setLineDash([5 / scale, 5 / scale]);
            else ctx.setLineDash([]);

            ctx.ellipse(-c, 0, a, b, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);
          }
      });

      // 5. Sun
      const sun = PLANETS[0];
      const coronaGrad = ctx.createRadialGradient(0, 0, sun.radius, 0, 0, sun.radius * 4);
      coronaGrad.addColorStop(0, 'rgba(255, 200, 0, 0.4)');
      coronaGrad.addColorStop(0.5, 'rgba(255, 100, 0, 0.1)');
      coronaGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = coronaGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius * 4, 0, Math.PI * 2);
      ctx.fill();

      const sunBodyGrad = ctx.createRadialGradient(0, 0, sun.radius * 0.2, 0, 0, sun.radius);
      sunBodyGrad.addColorStop(0, '#FFF');
      sunBodyGrad.addColorStop(0.4, '#FDB813');
      sunBodyGrad.addColorStop(1, '#FF8C00');
      ctx.fillStyle = sunBodyGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius, 0, Math.PI * 2);
      ctx.fill();

      // 6. Planets & Moons
      planetsRuntime.current.forEach((rtPlanet, index) => {
        const config = PLANETS[index];
        if (config.type === 'star') return;
        if (config.type === 'comet' && !showComets) return;

        // Draw Trails
        if (rtPlanet.trail.length > 1) {
          ctx.beginPath();
          ctx.strokeStyle = config.color;
          ctx.lineWidth = Math.max(1, 1/scale);
          ctx.globalAlpha = config.type === 'comet' ? 0.6 : 0.3;
          rtPlanet.trail.forEach((point, i) => {
            if (i === 0) ctx.moveTo(point.x, point.y);
            else ctx.lineTo(point.x, point.y);
          });
          ctx.stroke();
          ctx.globalAlpha = 1.0;
        }

        const x = rtPlanet.visualX;
        const y = rtPlanet.visualY;
        const radius = config.radius * PLANET_SCALE_FACTOR;

        // Comet Tail Logic (Always points away from Sun)
        if (config.type === 'comet') {
           const distToSun = Math.sqrt(x*x + y*y);
           // Tail gets longer and brighter when closer to sun
           const maxTailLen = 100;
           const tailStrength = Math.min(1, 400 / distToSun); 

           if (tailStrength > 0.1) {
             const angleFromSun = Math.atan2(y, x);
             ctx.save();
             ctx.translate(x, y);
             ctx.rotate(angleFromSun);

             const tailGrad = ctx.createLinearGradient(0, 0, maxTailLen * tailStrength, 0);
             tailGrad.addColorStop(0, 'rgba(200, 230, 255, 0.8)');
             tailGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');

             ctx.fillStyle = tailGrad;
             ctx.beginPath();
             ctx.moveTo(0, -radius);
             ctx.lineTo(maxTailLen * tailStrength, 0);
             ctx.lineTo(0, radius);
             ctx.fill();
             ctx.restore();
           }
        }

        ctx.save();
        ctx.translate(x, y);

        if (config.name === 'Bumi' || config.name === 'Venus') {
            const atmoGrad = ctx.createRadialGradient(0, 0, radius, 0, 0, radius * 1.3);
            atmoGrad.addColorStop(0, (config.colors[2] || config.color) + '88');
            atmoGrad.addColorStop(1, 'rgba(0,0,0,0)');
            ctx.fillStyle = atmoGrad;
            ctx.beginPath();
            ctx.arc(0, 0, radius * 1.3, 0, Math.PI * 2);
            ctx.fill();
        }

        // Fix: Removed unused surfGrad variable
        if (config.colors.length > 2) {
             const angle = Math.PI / 4;
             const planetCtx = ctx.createLinearGradient(
                 -radius * Math.cos(angle), -radius * Math.sin(angle),
                 radius * Math.cos(angle), radius * Math.sin(angle)
             );
             config.colors.forEach((col, idx) => {
                 planetCtx.addColorStop(idx / (config.colors.length - 1), col);
             });
             ctx.fillStyle = planetCtx;
        } else {
             ctx.fillStyle = config.color;
        }

        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();

        if (config.hasRing) {
             ctx.save();
             ctx.rotate(Math.PI / 6);
             ctx.beginPath();
             ctx.strokeStyle = '#CDBA96';
             ctx.lineWidth = radius * 0.8;
             ctx.globalAlpha = 0.7;
             ctx.ellipse(0, 0, radius * 2.2, radius * 0.6, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.beginPath();
             ctx.strokeStyle = '#000';
             ctx.lineWidth = radius * 0.1;
             ctx.globalAlpha = 0.5;
             ctx.ellipse(0, 0, radius * 1.8, radius * 0.5, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.restore();
        }

        // Shadow Logic
        const angleToSun = Math.atan2(-y, -x);
        ctx.rotate(angleToSun);

        ctx.beginPath();
        ctx.fillStyle = 'rgba(0,0,0,0.75)';
        ctx.arc(0, 0, radius, Math.PI / 2, -Math.PI / 2); 
        ctx.fill();

        const shadowGrad = ctx.createLinearGradient(-radius/2, 0, radius/2, 0);
        shadowGrad.addColorStop(0, 'rgba(0,0,0,0.8)');
        shadowGrad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = shadowGrad;
        ctx.fillRect(-radius/2, -radius, radius, radius*2);

        ctx.restore();

        if (config.moons && rtPlanet.moons && scale > 0.15) {
          config.moons.forEach((moon, mIndex) => {
            const mAngle = rtPlanet.moons[mIndex].angle;
            const mx = x + Math.cos(mAngle) * moon.distance;
            const my = y + Math.sin(mAngle) * moon.distance;

            ctx.fillStyle = moon.color;
            ctx.beginPath();
            ctx.arc(mx, my, moon.radius, 0, Math.PI * 2);
            ctx.fill();

            const moonAngleToSun = Math.atan2(-my, -mx);
            ctx.save();
            ctx.translate(mx, my);
            ctx.rotate(moonAngleToSun);
            ctx.fillStyle = 'rgba(0,0,0,0.8)';
            ctx.beginPath();
            ctx.arc(0, 0, moon.radius, Math.PI/2, -Math.PI/2);
            ctx.fill();
            ctx.restore();

            if (selectedPlanet?.name === moon.name || hoveredPlanet?.name === moon.name) {
                ctx.strokeStyle = 'white';
                ctx.lineWidth = 1 / scale;
                ctx.beginPath();
                ctx.arc(mx, my, moon.radius + (2/scale), 0, Math.PI * 2);
                ctx.stroke();
            }
          });
        }

        if (selectedPlanet?.name === config.name || hoveredPlanet?.name === config.name) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 2 / scale;
          ctx.beginPath();
          ctx.arc(x, y, radius + (4/scale), 0, Math.PI * 2);
          ctx.stroke();
        }

        if (scale < 0.25 || selectedPlanet?.name === config.name) {
          ctx.fillStyle = '#EEE';
          ctx.font = `bold ${12/scale}px "Segoe UI", sans-serif`;
          ctx.textAlign = 'center';
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 4;
          ctx.fillText(config.name, x, y - (radius + 12/scale));
          ctx.shadowBlur = 0;
        }
      });

      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animationFrameId);
  }, [stars, asteroids, isPlaying, following, selectedPlanet, hoveredPlanet, showHabitableZone, showComets]);

  const handleWheel = (e: React.WheelEvent) => {
    const scale = simulationState.current.scale;
    const zoomSensitivity = 0.001 * scale; 
    let newScale = scale - e.deltaY * zoomSensitivity;
    newScale = Math.max(0.01, Math.min(newScale, 5));
    simulationState.current.scale = newScale;
    setUiZoom(newScale);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    simulationState.current.isDragging = true;
    simulationState.current.lastMouseX = e.clientX;
    simulationState.current.lastMouseY = e.clientY;
    if (following) setFollowing(null);
  };

  const handleMouseUp = () => {
    simulationState.current.isDragging = false;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (simulationState.current.isDragging) {
      const dx = e.clientX - simulationState.current.lastMouseX;
      const dy = e.clientY - simulationState.current.lastMouseY;
      simulationState.current.offsetX += dx;
      simulationState.current.offsetY += dy;
      simulationState.current.lastMouseX = e.clientX;
      simulationState.current.lastMouseY = e.clientY;
      setHoveredPlanet(null);
      return;
    }

    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    const width = canvas.width; 
    const height = canvas.height;
    const cx = width / 2;
    const cy = height / 2;
    const { scale, offsetX, offsetY } = simulationState.current;

    let found: PlanetConfig | MoonConfig | null = null;

    for (let i = 0; i < planetsRuntime.current.length; i++) {
      const rtP = planetsRuntime.current[i];
      const config = PLANETS[i];

      if (config.type === 'comet' && !showComets) continue;

      let pX = rtP.visualX;
      let pY = rtP.visualY;
      if (config.type === 'star') { pX = 0; pY = 0; }

      const screenX = cx + offsetX + pX * scale;
      const screenY = cy + offsetY + pY * scale;

      // Check Moons first
      if (config.moons && rtP.moons && scale > 0.15) {
         for(let m=0; m<config.moons.length; m++) {
             const moon = config.moons[m];
             const rtMoon = rtP.moons[m];
             const mx = pX + Math.cos(rtMoon.angle) * moon.distance;
             const my = pY + Math.sin(rtMoon.angle) * moon.distance;

             const screenMX = cx + offsetX + mx * scale;
             const screenMY = cy + offsetY + my * scale;

             const mHitRadius = Math.max(moon.radius * scale, 6); 
             const mDist = Math.hypot(mouseX - screenMX, mouseY - screenMY);

             if (mDist < mHitRadius) {
                 // FIX: Use 'as const' to satisfy TypeScript strict literal types
                 found = { ...moon, type: 'moon' as const };
                 break;
             }
         }
      }

      if (found) break;

      const hitRadius = Math.max(config.radius * scale, 12);
      const dist = Math.hypot(mouseX - screenX, mouseY - screenY);

      if (dist < hitRadius) {
        found = config;
        break;
      }
    }

    setHoveredPlanet(found);
    if (found) {
      setCursorPos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleClick = () => {
    if (hoveredPlanet) {
      setSelectedPlanet(hoveredPlanet);
      if (hoveredPlanet.type !== 'moon') {
        setFollowing(hoveredPlanet.name);
      }
    }
  };

  const handleSelectPlanet = (p: PlanetConfig) => {
    setSelectedPlanet(p);
    setFollowing(p.name);
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      <Controls 
        speed={uiSpeed} setSpeed={setUiSpeed} 
        zoom={uiZoom} setZoom={setUiZoom} 
        isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}
        date={simulationDate}
        onSelectPlanet={handleSelectPlanet}
        following={following}
        showHabitableZone={showHabitableZone}
        setShowHabitableZone={setShowHabitableZone}
        showComets={showComets}
        setShowComets={setShowComets}
      />

      <canvas
        ref={canvasRef}
        className={`block w-full h-full ${simulationState.current.isDragging ? 'cursor-grabbing' : hoveredPlanet ? 'cursor-pointer' : 'cursor-default'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onMouseMove={handleMouseMove}
        onClick={handleClick}
      />

      {!selectedPlanet && (
        <Tooltip x={cursorPos.x} y={cursorPos.y} planet={hoveredPlanet} />
      )}

      <SidePanel 
        planet={selectedPlanet} 
        onClose={() => setSelectedPlanet(null)} 
        onFollow={(name) => setFollowing(name === following ? null : name)}
        isFollowing={!!(selectedPlanet && following === selectedPlanet.name)}
      />
    </div>
  );
};

export default SolarSystem;

import React from 'react';
import { PlanetConfig, MoonConfig } from '../types';

interface SidePanelProps {
  planet: PlanetConfig | MoonConfig | null;
  onClose: () => void;
  onFollow: (planetName: string) => void;
  isFollowing: boolean;
}

export const SidePanel: React.FC<SidePanelProps> = ({ planet, onClose, onFollow, isFollowing }) => {
  if (!planet) return null;

  const isMoon = planet.type === 'moon';
  const isDwarf = planet.type === 'dwarf';
  const isComet = planet.type === 'comet';

  return (
    <div className="absolute top-0 right-0 h-full w-full md:w-96 bg-black/80 backdrop-blur-xl border-l border-white/10 p-6 z-50 transform transition-transform duration-300 ease-in-out shadow-2xl flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-white to-gray-400">
          {planet.name}
        </h2>
        <button 
          onClick={onClose}
          className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center transition-colors"
        >
          <i className="fas fa-times text-white"></i>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 space-y-6 custom-scrollbar">
        {/* Preview Circle */}
        <div className="flex justify-center py-4">
          <div 
            className="w-32 h-32 rounded-full shadow-[0_0_30px_rgba(255,255,255,0.2)]"
            style={{ 
              backgroundColor: planet.color,
              background: `radial-gradient(circle at 30% 30%, ${planet.color}, #000)`
            }}
          />
        </div>

        <div className="bg-white/5 p-4 rounded-xl border border-white/5">
          {isDwarf && <span className="inline-block px-2 py-0.5 mb-2 rounded bg-purple-500/20 text-purple-300 text-[10px] font-bold uppercase border border-purple-500/50">Planet Kerdil</span>}
          {isComet && <span className="inline-block px-2 py-0.5 mb-2 rounded bg-cyan-500/20 text-cyan-300 text-[10px] font-bold uppercase border border-cyan-500/50">Komet</span>}
          <p className="text-gray-300 text-sm leading-relaxed text-justify">{planet.description}</p>
        </div>

        {/* Conditional Rendering based on type */}
        {!isMoon ? (() => {
          // Explicit cast for TS safety inside this block
          const p = planet as PlanetConfig;
          return (
          <>
            <div className="space-y-4">
              <h3 className="text-xs uppercase tracking-widest text-gray-500 font-bold border-b border-gray-800 pb-2">Statistik Utama</h3>

              <div className="grid grid-cols-2 gap-3">
                <StatBox label="Jarak (AU)" value={p.distance.toString()} icon="fa-arrows-left-right" />
                <StatBox label="Diameter" value={p.diameter} icon="fa-ruler-combined" />
                <StatBox label="Suhu" value={p.temp} icon="fa-temperature-half" />
                <StatBox label="Rotasi" value={p.dayLength} icon="fa-rotate" />
                <StatBox label="Revolusi" value={p.yearLength} icon="fa-circle-notch" />
              </div>
            </div>

            {/* Moon List (Only for Planets) */}
            {p.moons && p.moons.length > 0 && (
              <div className="space-y-3">
                <h3 className="text-xs uppercase tracking-widest text-gray-500 font-bold border-b border-gray-800 pb-2 flex items-center gap-2">
                  <i className="fas fa-moon text-[10px]"></i> Satelit Alami Utama
                </h3>
                <div className="space-y-3">
                  {p.moons.map((moon) => (
                    <div key={moon.name} className="bg-white/5 p-3 rounded-lg border border-white/5 hover:bg-white/10 transition-colors">
                      <div className="flex items-center gap-2 mb-1">
                        <div className="w-2 h-2 rounded-full" style={{ backgroundColor: moon.color }}></div>
                        <span className="font-bold text-sm text-gray-200">{moon.name}</span>
                      </div>
                      <p className="text-xs text-gray-400 leading-snug">{moon.description}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="bg-blue-900/20 p-4 rounded-xl border border-blue-500/20 mt-4">
              <div className="flex items-start gap-3">
                <i className="fas fa-lightbulb text-yellow-400 mt-1"></i>
                <div>
                  <h4 className="font-bold text-blue-200 text-sm mb-1">Tahukah Kamu?</h4>
                  <p className="text-xs text-blue-100/80 leading-relaxed">{p.funFact}</p>
                </div>
              </div>
            </div>
          </>
          );
        })() : (
           /* Moon View */
           <div className="space-y-4">
              <div className="bg-white/5 p-3 rounded-lg flex items-center gap-3">
                 <i className="fas fa-circle-notch text-gray-400"></i>
                 <div>
                    <div className="text-[10px] uppercase text-gray-500 font-bold">Tipe Objek</div>
                    <div className="text-white text-sm">Satelit Alami (Bulan)</div>
                 </div>
              </div>
           </div>
        )}
      </div>

      {!isMoon && (
        <div className="mt-6 pt-4 border-t border-white/10">
          <button 
            onClick={() => onFollow(planet.name)}
            className={`w-full py-3 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${
              isFollowing 
                ? 'bg-red-500/20 text-red-400 border border-red-500/50 hover:bg-red-500/30' 
                : 'bg-white text-black hover:bg-gray-200'
            }`}
          >
            <i className={`fas ${isFollowing ? 'fa-video-slash' : 'fa-video'}`}></i>
            {isFollowing ? 'Berhenti Mengikuti' : 'Ikuti Objek Ini'}
          </button>
        </div>
      )}
    </div>
  );
};

const StatBox = ({ label, value, icon }: { label: string, value: string, icon: string }) => (
  <div className="bg-white/5 p-3 rounded-lg">
    <div className="flex items-center gap-2 text-gray-400 text-[10px] mb-1 uppercase font-semibold">
      <i className={`fas ${icon}`}></i>
      {label}
    </div>
    <div className="text-white text-sm font-medium break-words leading-tight">{value}</div>
  </div>
);

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { PLANETS, generateStars, generateAsteroids } from '../constants';
import { PlanetConfig, PlanetRuntimeState, MoonConfig } from '../types';
import { Tooltip } from './Tooltip';
import { Controls } from './Controls';
import { SidePanel } from './SidePanel';

// Scale Factors
const AU_PIXELS = 120; // Scale Distance
const PLANET_SCALE_FACTOR = 1; // Base scale for planet sizes

const SolarSystem: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [hoveredPlanet, setHoveredPlanet] = useState<PlanetConfig | MoonConfig | null>(null);
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetConfig | MoonConfig | null>(null); 
  const [following, setFollowing] = useState<string | null>(null); 

  const [cursorPos, setCursorPos] = useState({ x: 0, y: 0 });
  const [uiSpeed, setUiSpeed] = useState(1);
  const [uiZoom, setUiZoom] = useState(0.4); // Start zoomed out a bit more
  const [isPlaying, setIsPlaying] = useState(true);
  const [simulationDate, setSimulationDate] = useState(Date.now());

  // New Visualization States
  const [showHabitableZone, setShowHabitableZone] = useState(false);
  const [showComets, setShowComets] = useState(true);

  // Simulation State
  const simulationState = useRef({
    scale: 0.4,
    speedMultiplier: 1,
    offsetX: 0,
    offsetY: 0,
    isDragging: false,
    lastMouseX: 0,
    lastMouseY: 0,
  });

  const planetsRuntime = useRef<PlanetRuntimeState[]>(
    PLANETS.map(p => ({
      name: p.name,
      angle: Math.random() * Math.PI * 2,
      visualX: 0,
      visualY: 0,
      trail: [],
      moons: p.moons ? p.moons.map(() => ({ angle: Math.random() * Math.PI * 2 })) : []
    }))
  );

  const stars = useMemo(() => generateStars(1000), []);
  const asteroids = useMemo(() => generateAsteroids(500), []);

  useEffect(() => { simulationState.current.speedMultiplier = uiSpeed; }, [uiSpeed]);
  useEffect(() => { simulationState.current.scale = uiZoom; }, [uiZoom]);

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    let animationFrameId: number;

    const render = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }

      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      const { scale, offsetX, offsetY, speedMultiplier } = simulationState.current;

      // --- PHYSICS UPDATE ---
      if (isPlaying) {
        setSimulationDate(d => d + (speedMultiplier * 86400 * 1000 * 0.1));

        planetsRuntime.current.forEach((rtPlanet, index) => {
          const config = PLANETS[index];
          // Physics for Planets, Dwarfs, and Comets
          if (config.type === 'planet' || config.type === 'dwarf' || config.type === 'comet') {

            // Variable speed based on Kepler's 2nd Law (faster near perihelion)
            // Calculate r (distance) for current angle to adjust speed
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const currentR = (a * (1 - e * e)) / (1 + e * Math.cos(rtPlanet.angle));
            const normalizedR = currentR / (a); 
            // Simplified viscosity: closer = faster.
            const keplerSpeed = config.speed * (1 / (normalizedR * normalizedR)); 

            rtPlanet.angle += (keplerSpeed * 0.002) * speedMultiplier;

            // ELLIPTICAL ORBIT CALCULATION
            const b = a * Math.sqrt(1 - e*e); // Semi-minor axis
            const c = a * e; // Distance from center to focus (Sun)

            // Current position relative to Ellipse Center
            let ex = a * Math.cos(rtPlanet.angle);
            let ey = b * Math.sin(rtPlanet.angle);

            // Shift so Sun (focus) is at (0,0)
            rtPlanet.visualX = ex - c; 
            rtPlanet.visualY = ey;

            // Trail Logic
            if (rtPlanet.trail.length > 80) rtPlanet.trail.shift();
            // Comets leave denser trails
            const trailFrequency = config.type === 'comet' ? 5 : 20;
            if (Math.floor(Date.now() / trailFrequency) % 2 === 0) {
                rtPlanet.trail.push({ x: rtPlanet.visualX, y: rtPlanet.visualY });
            }

            // Update Moons
            if (config.moons && rtPlanet.moons) {
              config.moons.forEach((moon, mIndex) => {
                rtPlanet.moons[mIndex].angle += (moon.speed * 0.02) * speedMultiplier;
              });
            }
          }
        });

        asteroids.forEach(ast => {
            ast.angle += (ast.speed * 0.002) * speedMultiplier;
        });
      }

      // --- CAMERA UPDATE ---
      let currentOffsetX = offsetX;
      let currentOffsetY = offsetY;

      if (following) {
        // Find planet or moon to follow
        let targetX = 0;
        let targetY = 0;
        let foundTarget = false;

        const targetPlanet = planetsRuntime.current.find(p => p.name === following);
        if (targetPlanet) {
            targetX = targetPlanet.visualX;
            targetY = targetPlanet.visualY;
            foundTarget = true;
        } else {
             // Check if it's a moon
             for(let i=0; i<PLANETS.length; i++) {
                 const pConfig = PLANETS[i];
                 const pRuntime = planetsRuntime.current[i];
                 if(pConfig.moons && pRuntime.moons) {
                     const mIndex = pConfig.moons.findIndex(m => m.name === following);
                     if(mIndex !== -1) {
                         const mConfig = pConfig.moons[mIndex];
                         const mRuntime = pRuntime.moons[mIndex];
                         targetX = pRuntime.visualX + Math.cos(mRuntime.angle) * mConfig.distance;
                         targetY = pRuntime.visualY + Math.sin(mRuntime.angle) * mConfig.distance;
                         foundTarget = true;
                         break;
                     }
                 }
             }
        }

        if (foundTarget) {
            simulationState.current.offsetX = -targetX;
            simulationState.current.offsetY = -targetY;
            currentOffsetX = -targetX;
            currentOffsetY = -targetY;
        }
      }

      // --- DRAWING ---

      // 1. Background (Space)
      ctx.fillStyle = '#020205'; 
      ctx.fillRect(0, 0, width, height);

      const nebulaGrad = ctx.createRadialGradient(width/2, height/2, width * 0.2, width/2, height/2, width * 1.5);
      nebulaGrad.addColorStop(0, '#0a0b14');
      nebulaGrad.addColorStop(1, '#000000');
      ctx.fillStyle = nebulaGrad;
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(cx + currentOffsetX, cy + currentOffsetY);
      ctx.scale(scale, scale);

      // 2. Stars
      const parallaxScale = Math.max(0.1, 1/scale);
      stars.forEach(star => {
        ctx.globalAlpha = star.opacity;
        ctx.fillStyle = star.color;
        ctx.beginPath();
        ctx.arc(star.x * parallaxScale, star.y * parallaxScale, star.size / scale, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 3. Asteroid Belt
      ctx.fillStyle = '#555';
      asteroids.forEach(ast => {
        const r = ast.distance * AU_PIXELS;
        const x = Math.cos(ast.angle) * r;
        const y = Math.sin(ast.angle) * r;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.arc(x, y, (ast.size / scale), 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 4. Orbit Lines & Habitable Zone

      // Habitable Zone (Goldilocks Zone)
      if (showHabitableZone) {
          const hzInner = 0.95 * AU_PIXELS;
          const hzOuter = 1.37 * AU_PIXELS;
          ctx.beginPath();
          ctx.arc(0, 0, hzInner, 0, Math.PI * 2);
          ctx.arc(0, 0, hzOuter, 0, Math.PI * 2, true); // Create ring
          ctx.fillStyle = 'rgba(0, 255, 100, 0.1)';
          ctx.fill();
          ctx.strokeStyle = 'rgba(0, 255, 100, 0.2)';
          ctx.lineWidth = 1 / scale;
          ctx.stroke();
      }

      ctx.lineWidth = Math.max(0.5, 0.5 / scale);

      // Fix: Changed 'rtP' to '_' to ignore unused parameter
      planetsRuntime.current.forEach((_, i) => {
          const config = PLANETS[i];
          if (config.type === 'comet' && !showComets) return;

          if (config.type === 'planet' || config.type === 'dwarf' || config.type === 'comet') {
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const b = a * Math.sqrt(1 - e*e);
            const c = a * e;
            ctx.beginPath();
            ctx.strokeStyle = config.type === 'comet' ? 'rgba(255,255,255,0.1)' : (config.type === 'dwarf' ? '#555' : '#333');
            // Dashed line for comets/dwarfs
            if (config.type !== 'planet') ctx.setLineDash([5 / scale, 5 / scale]);
            else ctx.setLineDash([]);

            ctx.ellipse(-c, 0, a, b, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);
          }
      });

      // 5. Sun
      const sun = PLANETS[0];
      const coronaGrad = ctx.createRadialGradient(0, 0, sun.radius, 0, 0, sun.radius * 4);
      coronaGrad.addColorStop(0, 'rgba(255, 200, 0, 0.4)');
      coronaGrad.addColorStop(0.5, 'rgba(255, 100, 0, 0.1)');
      coronaGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = coronaGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius * 4, 0, Math.PI * 2);
      ctx.fill();

      const sunBodyGrad = ctx.createRadialGradient(0, 0, sun.radius * 0.2, 0, 0, sun.radius);
      sunBodyGrad.addColorStop(0, '#FFF');
      sunBodyGrad.addColorStop(0.4, '#FDB813');
      sunBodyGrad.addColorStop(1, '#FF8C00');
      ctx.fillStyle = sunBodyGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius, 0, Math.PI * 2);
      ctx.fill();

      // 6. Planets & Moons
      planetsRuntime.current.forEach((rtPlanet, index) => {
        const config = PLANETS[index];
        if (config.type === 'star') return;
        if (config.type === 'comet' && !showComets) return;

        // Draw Trails
        if (rtPlanet.trail.length > 1) {
          ctx.beginPath();
          ctx.strokeStyle = config.color;
          ctx.lineWidth = Math.max(1, 1/scale);
          ctx.globalAlpha = config.type === 'comet' ? 0.6 : 0.3;
          rtPlanet.trail.forEach((point, i) => {
            if (i === 0) ctx.moveTo(point.x, point.y);
            else ctx.lineTo(point.x, point.y);
          });
          ctx.stroke();
          ctx.globalAlpha = 1.0;
        }

        const x = rtPlanet.visualX;
        const y = rtPlanet.visualY;
        const radius = config.radius * PLANET_SCALE_FACTOR;

        // Comet Tail Logic (Always points away from Sun)
        if (config.type === 'comet') {
           const distToSun = Math.sqrt(x*x + y*y);
           // Tail gets longer and brighter when closer to sun
           const maxTailLen = 100;
           const tailStrength = Math.min(1, 400 / distToSun); 

           if (tailStrength > 0.1) {
             const angleFromSun = Math.atan2(y, x);
             ctx.save();
             ctx.translate(x, y);
             ctx.rotate(angleFromSun);

             const tailGrad = ctx.createLinearGradient(0, 0, maxTailLen * tailStrength, 0);
             tailGrad.addColorStop(0, 'rgba(200, 230, 255, 0.8)');
             tailGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');

             ctx.fillStyle = tailGrad;
             ctx.beginPath();
             ctx.moveTo(0, -radius);
             ctx.lineTo(maxTailLen * tailStrength, 0);
             ctx.lineTo(0, radius);
             ctx.fill();
             ctx.restore();
           }
        }

        ctx.save();
        ctx.translate(x, y);

        if (config.name === 'Bumi' || config.name === 'Venus') {
            const atmoGrad = ctx.createRadialGradient(0, 0, radius, 0, 0, radius * 1.3);
            atmoGrad.addColorStop(0, (config.colors[2] || config.color) + '88');
            atmoGrad.addColorStop(1, 'rgba(0,0,0,0)');
            ctx.fillStyle = atmoGrad;
            ctx.beginPath();
            ctx.arc(0, 0, radius * 1.3, 0, Math.PI * 2);
            ctx.fill();
        }

        // Fix: Removed unused surfGrad variable
        if (config.colors.length > 2) {
             const angle = Math.PI / 4;
             const planetCtx = ctx.createLinearGradient(
                 -radius * Math.cos(angle), -radius * Math.sin(angle),
                 radius * Math.cos(angle), radius * Math.sin(angle)
             );
             config.colors.forEach((col, idx) => {
                 planetCtx.addColorStop(idx / (config.colors.length - 1), col);
             });
             ctx.fillStyle = planetCtx;
        } else {
             ctx.fillStyle = config.color;
        }

        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();

        if (config.hasRing) {
             ctx.save();
             ctx.rotate(Math.PI / 6);
             ctx.beginPath();
             ctx.strokeStyle = '#CDBA96';
             ctx.lineWidth = radius * 0.8;
             ctx.globalAlpha = 0.7;
             ctx.ellipse(0, 0, radius * 2.2, radius * 0.6, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.beginPath();
             ctx.strokeStyle = '#000';
             ctx.lineWidth = radius * 0.1;
             ctx.globalAlpha = 0.5;
             ctx.ellipse(0, 0, radius * 1.8, radius * 0.5, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.restore();
        }

        // Shadow Logic
        const angleToSun = Math.atan2(-y, -x);
        ctx.rotate(angleToSun);

        ctx.beginPath();
        ctx.fillStyle = 'rgba(0,0,0,0.75)';
        ctx.arc(0, 0, radius, Math.PI / 2, -Math.PI / 2); 
        ctx.fill();

        const shadowGrad = ctx.createLinearGradient(-radius/2, 0, radius/2, 0);
        shadowGrad.addColorStop(0, 'rgba(0,0,0,0.8)');
        shadowGrad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = shadowGrad;
        ctx.fillRect(-radius/2, -radius, radius, radius*2);

        ctx.restore();

        if (config.moons && rtPlanet.moons && scale > 0.15) {
          config.moons.forEach((moon, mIndex) => {
            const mAngle = rtPlanet.moons[mIndex].angle;
            const mx = x + Math.cos(mAngle) * moon.distance;
            const my = y + Math.sin(mAngle) * moon.distance;

            ctx.fillStyle = moon.color;
            ctx.beginPath();
            ctx.arc(mx, my, moon.radius, 0, Math.PI * 2);
            ctx.fill();

            const moonAngleToSun = Math.atan2(-my, -mx);
            ctx.save();
            ctx.translate(mx, my);
            ctx.rotate(moonAngleToSun);
            ctx.fillStyle = 'rgba(0,0,0,0.8)';
            ctx.beginPath();
            ctx.arc(0, 0, moon.radius, Math.PI/2, -Math.PI/2);
            ctx.fill();
            ctx.restore();

            if (selectedPlanet?.name === moon.name || hoveredPlanet?.name === moon.name) {
                ctx.strokeStyle = 'white';
                ctx.lineWidth = 1 / scale;
                ctx.beginPath();
                ctx.arc(mx, my, moon.radius + (2/scale), 0, Math.PI * 2);
                ctx.stroke();
            }
          });
        }

        if (selectedPlanet?.name === config.name || hoveredPlanet?.name === config.name) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 2 / scale;
          ctx.beginPath();
          ctx.arc(x, y, radius + (4/scale), 0, Math.PI * 2);
          ctx.stroke();
        }

        if (scale < 0.25 || selectedPlanet?.name === config.name) {
          ctx.fillStyle = '#EEE';
          ctx.font = `bold ${12/scale}px "Segoe UI", sans-serif`;
          ctx.textAlign = 'center';
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 4;
          ctx.fillText(config.name, x, y - (radius + 12/scale));
          ctx.shadowBlur = 0;
        }
      });

      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animationFrameId);
  }, [stars, asteroids, isPlaying, following, selectedPlanet, hoveredPlanet, showHabitableZone, showComets]);

  const handleWheel = (e: React.WheelEvent) => {
    const scale = simulationState.current.scale;
    const zoomSensitivity = 0.001 * scale; 
    let newScale = scale - e.deltaY * zoomSensitivity;
    newScale = Math.max(0.01, Math.min(newScale, 5));
    simulationState.current.scale = newScale;
    setUiZoom(newScale);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    simulationState.current.isDragging = true;
    simulationState.current.lastMouseX = e.clientX;
    simulationState.current.lastMouseY = e.clientY;
    if (following) setFollowing(null);
  };

  const handleMouseUp = () => {
    simulationState.current.isDragging = false;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (simulationState.current.isDragging) {
      const dx = e.clientX - simulationState.current.lastMouseX;
      const dy = e.clientY - simulationState.current.lastMouseY;
      simulationState.current.offsetX += dx;
      simulationState.current.offsetY += dy;
      simulationState.current.lastMouseX = e.clientX;
      simulationState.current.lastMouseY = e.clientY;
      setHoveredPlanet(null);
      return;
    }

    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    const width = canvas.width; 
    const height = canvas.height;
    const cx = width / 2;
    const cy = height / 2;
    const { scale, offsetX, offsetY } = simulationState.current;

    let found: PlanetConfig | MoonConfig | null = null;

    for (let i = 0; i < planetsRuntime.current.length; i++) {
      const rtP = planetsRuntime.current[i];
      const config = PLANETS[i];

      if (config.type === 'comet' && !showComets) continue;

      let pX = rtP.visualX;
      let pY = rtP.visualY;
      if (config.type === 'star') { pX = 0; pY = 0; }

      const screenX = cx + offsetX + pX * scale;
      const screenY = cy + offsetY + pY * scale;

      // Check Moons first
      if (config.moons && rtP.moons && scale > 0.15) {
         for(let m=0; m<config.moons.length; m++) {
             const moon = config.moons[m];
             const rtMoon = rtP.moons[m];
             const mx = pX + Math.cos(rtMoon.angle) * moon.distance;
             const my = pY + Math.sin(rtMoon.angle) * moon.distance;

             const screenMX = cx + offsetX + mx * scale;
             const screenMY = cy + offsetY + my * scale;

             const mHitRadius = Math.max(moon.radius * scale, 6); 
             const mDist = Math.hypot(mouseX - screenMX, mouseY - screenMY);

             if (mDist < mHitRadius) {
                 // FIX: Use 'as const' to satisfy TypeScript strict literal types
                 found = { ...moon, type: 'moon' as const };
                 break;
             }
         }
      }

      if (found) break;

      const hitRadius = Math.max(config.radius * scale, 12);
      const dist = Math.hypot(mouseX - screenX, mouseY - screenY);

      if (dist < hitRadius) {
        found = config;
        break;
      }
    }

    setHoveredPlanet(found);
    if (found) {
      setCursorPos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleClick = () => {
    if (hoveredPlanet) {
      handleSelectPlanet(hoveredPlanet);
    }
  };

  const handleSelectPlanet = (p: PlanetConfig | MoonConfig) => {
    setSelectedPlanet(p);
    setFollowing(p.name);

    // Auto-zoom logic based on radius
    // Smaller radius = Larger zoom
    const r = p.radius;
    // Heuristic: Try to make the planet decent size on screen
    const targetZoom = Math.min(Math.max(20 / r, 0.5), 3.5);

    setUiZoom(targetZoom);
    simulationState.current.scale = targetZoom;
  };

  const handleSidePanelFollow = (name: string) => {
      if (following === name) {
          setFollowing(null);
      } else {
          // Find the planet/moon object to calculate correct zoom
          let target: PlanetConfig | MoonConfig | undefined = PLANETS.find(p => p.name === name);
          if (!target) {
              // Check moons
              PLANETS.forEach(p => {
                  if (p.moons) {
                      const m = p.moons.find(m => m.name === name);
                      if (m) target = m;
                  }
              });
          }

          setFollowing(name);

          if (target) {
              const r = target.radius;
              const targetZoom = Math.min(Math.max(20 / r, 0.5), 3.5);
              setUiZoom(targetZoom);
              simulationState.current.scale = targetZoom;
          }
      }
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      <Controls 
        speed={uiSpeed} setSpeed={setUiSpeed} 
        zoom={uiZoom} setZoom={setUiZoom} 
        isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}
        date={simulationDate}
        onSelectPlanet={(p) => handleSelectPlanet(p)}
        following={following}
        showHabitableZone={showHabitableZone}
        setShowHabitableZone={setShowHabitableZone}
        showComets={showComets}
        setShowComets={setShowComets}
      />

      <canvas
        ref={canvasRef}
        className={`block w-full h-full ${simulationState.current.isDragging ? 'cursor-grabbing' : hoveredPlanet ? 'cursor-pointer' : 'cursor-default'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onMouseMove={handleMouseMove}
        onClick={handleClick}
      />

      {!selectedPlanet && (
        <Tooltip x={cursorPos.x} y={cursorPos.y} planet={hoveredPlanet} />
      )}

      <SidePanel 
        planet={selectedPlanet} 
        onClose={() => setSelectedPlanet(null)} 
        onFollow={handleSidePanelFollow}
        isFollowing={!!(selectedPlanet && following === selectedPlanet.name)}
      />
    </div>
  );
};

export default SolarSystem;

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { PLANETS, generateStars, generateAsteroids } from '../constants';
import { PlanetConfig, PlanetRuntimeState, MoonConfig } from '../types';
import { Tooltip } from './Tooltip';
import { Controls } from './Controls';
import { SidePanel } from './SidePanel';

// Scale Factors
const AU_PIXELS = 120; // Scale Distance
const PLANET_SCALE_FACTOR = 1; // Base scale for planet sizes

const SolarSystem: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [hoveredPlanet, setHoveredPlanet] = useState<PlanetConfig | MoonConfig | null>(null);
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetConfig | MoonConfig | null>(null); 
  const [following, setFollowing] = useState<string | null>(null); 

  const [cursorPos, setCursorPos] = useState({ x: 0, y: 0 });
  const [uiSpeed, setUiSpeed] = useState(1);
  const [uiZoom, setUiZoom] = useState(0.4); // Start zoomed out a bit more
  const [isPlaying, setIsPlaying] = useState(true);
  const [simulationDate, setSimulationDate] = useState(Date.now());

  // New Visualization States
  const [showHabitableZone, setShowHabitableZone] = useState(false);
  const [showComets, setShowComets] = useState(true);

  // Simulation State
  const simulationState = useRef({
    scale: 0.4,
    speedMultiplier: 1,
    offsetX: 0,
    offsetY: 0,
    isDragging: false,
    lastMouseX: 0,
    lastMouseY: 0,
  });

  const planetsRuntime = useRef<PlanetRuntimeState[]>(
    PLANETS.map(p => ({
      name: p.name,
      angle: Math.random() * Math.PI * 2,
      visualX: 0,
      visualY: 0,
      trail: [],
      moons: p.moons ? p.moons.map(() => ({ angle: Math.random() * Math.PI * 2 })) : []
    }))
  );

  const stars = useMemo(() => generateStars(1000), []);
  const asteroids = useMemo(() => generateAsteroids(500), []);

  useEffect(() => { simulationState.current.speedMultiplier = uiSpeed; }, [uiSpeed]);
  useEffect(() => { simulationState.current.scale = uiZoom; }, [uiZoom]);

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    let animationFrameId: number;

    const render = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }

      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      const { scale, offsetX, offsetY, speedMultiplier } = simulationState.current;

      // --- PHYSICS UPDATE ---
      if (isPlaying) {
        setSimulationDate(d => d + (speedMultiplier * 86400 * 1000 * 0.1));

        planetsRuntime.current.forEach((rtPlanet, index) => {
          const config = PLANETS[index];
          // Physics for Planets, Dwarfs, and Comets
          if (config.type === 'planet' || config.type === 'dwarf' || config.type === 'comet') {

            // Variable speed based on Kepler's 2nd Law (faster near perihelion)
            // Calculate r (distance) for current angle to adjust speed
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const currentR = (a * (1 - e * e)) / (1 + e * Math.cos(rtPlanet.angle));
            const normalizedR = currentR / (a); 
            // Simplified viscosity: closer = faster.
            const keplerSpeed = config.speed * (1 / (normalizedR * normalizedR)); 

            rtPlanet.angle += (keplerSpeed * 0.002) * speedMultiplier;

            // ELLIPTICAL ORBIT CALCULATION
            const b = a * Math.sqrt(1 - e*e); // Semi-minor axis
            const c = a * e; // Distance from center to focus (Sun)

            // Current position relative to Ellipse Center
            let ex = a * Math.cos(rtPlanet.angle);
            let ey = b * Math.sin(rtPlanet.angle);

            // Shift so Sun (focus) is at (0,0)
            rtPlanet.visualX = ex - c; 
            rtPlanet.visualY = ey;

            // Trail Logic
            if (rtPlanet.trail.length > 80) rtPlanet.trail.shift();
            // Comets leave denser trails
            const trailFrequency = config.type === 'comet' ? 5 : 20;
            if (Math.floor(Date.now() / trailFrequency) % 2 === 0) {
                rtPlanet.trail.push({ x: rtPlanet.visualX, y: rtPlanet.visualY });
            }

            // Update Moons
            if (config.moons && rtPlanet.moons) {
              config.moons.forEach((moon, mIndex) => {
                rtPlanet.moons[mIndex].angle += (moon.speed * 0.02) * speedMultiplier;
              });
            }
          }
        });

        asteroids.forEach(ast => {
            ast.angle += (ast.speed * 0.002) * speedMultiplier;
        });
      }

      // --- CAMERA UPDATE ---
      let currentOffsetX = offsetX;
      let currentOffsetY = offsetY;

      if (following) {
        // Find planet or moon to follow
        let targetX = 0;
        let targetY = 0;
        let foundTarget = false;

        const targetPlanet = planetsRuntime.current.find(p => p.name === following);
        if (targetPlanet) {
            targetX = targetPlanet.visualX;
            targetY = targetPlanet.visualY;
            foundTarget = true;
        } else {
             // Check if it's a moon
             for(let i=0; i<PLANETS.length; i++) {
                 const pConfig = PLANETS[i];
                 const pRuntime = planetsRuntime.current[i];
                 if(pConfig.moons && pRuntime.moons) {
                     const mIndex = pConfig.moons.findIndex(m => m.name === following);
                     if(mIndex !== -1) {
                         const mConfig = pConfig.moons[mIndex];
                         const mRuntime = pRuntime.moons[mIndex];
                         targetX = pRuntime.visualX + Math.cos(mRuntime.angle) * mConfig.distance;
                         targetY = pRuntime.visualY + Math.sin(mRuntime.angle) * mConfig.distance;
                         foundTarget = true;
                         break;
                     }
                 }
             }
        }

        if (foundTarget) {
            simulationState.current.offsetX = -targetX;
            simulationState.current.offsetY = -targetY;
            currentOffsetX = -targetX;
            currentOffsetY = -targetY;
        }
      }

      // --- DRAWING ---

      // 1. Background (Space)
      ctx.fillStyle = '#020205'; 
      ctx.fillRect(0, 0, width, height);

      const nebulaGrad = ctx.createRadialGradient(width/2, height/2, width * 0.2, width/2, height/2, width * 1.5);
      nebulaGrad.addColorStop(0, '#0a0b14');
      nebulaGrad.addColorStop(1, '#000000');
      ctx.fillStyle = nebulaGrad;
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(cx + currentOffsetX, cy + currentOffsetY);
      ctx.scale(scale, scale);

      // 2. Stars
      const parallaxScale = Math.max(0.1, 1/scale);
      stars.forEach(star => {
        ctx.globalAlpha = star.opacity;
        ctx.fillStyle = star.color;
        ctx.beginPath();
        ctx.arc(star.x * parallaxScale, star.y * parallaxScale, star.size / scale, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 3. Asteroid Belt
      ctx.fillStyle = '#555';
      asteroids.forEach(ast => {
        const r = ast.distance * AU_PIXELS;
        const x = Math.cos(ast.angle) * r;
        const y = Math.sin(ast.angle) * r;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.arc(x, y, (ast.size / scale), 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 4. Orbit Lines & Habitable Zone

      // Habitable Zone (Goldilocks Zone)
      if (showHabitableZone) {
          const hzInner = 0.95 * AU_PIXELS;
          const hzOuter = 1.37 * AU_PIXELS;
          ctx.beginPath();
          ctx.arc(0, 0, hzInner, 0, Math.PI * 2);
          ctx.arc(0, 0, hzOuter, 0, Math.PI * 2, true); // Create ring
          ctx.fillStyle = 'rgba(0, 255, 100, 0.1)';
          ctx.fill();
          ctx.strokeStyle = 'rgba(0, 255, 100, 0.2)';
          ctx.lineWidth = 1 / scale;
          ctx.stroke();
      }

      ctx.lineWidth = Math.max(0.5, 0.5 / scale);

      // Fix: Changed 'rtP' to '_' to ignore unused parameter
      planetsRuntime.current.forEach((_, i) => {
          const config = PLANETS[i];
          if (config.type === 'comet' && !showComets) return;

          if (config.type === 'planet' || config.type === 'dwarf' || config.type === 'comet') {
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const b = a * Math.sqrt(1 - e*e);
            const c = a * e;
            ctx.beginPath();
            ctx.strokeStyle = config.type === 'comet' ? 'rgba(255,255,255,0.1)' : (config.type === 'dwarf' ? '#555' : '#333');
            // Dashed line for comets/dwarfs
            if (config.type !== 'planet') ctx.setLineDash([5 / scale, 5 / scale]);
            else ctx.setLineDash([]);

            ctx.ellipse(-c, 0, a, b, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);
          }
      });

      // 5. Sun
      const sun = PLANETS[0];
      const coronaGrad = ctx.createRadialGradient(0, 0, sun.radius, 0, 0, sun.radius * 4);
      coronaGrad.addColorStop(0, 'rgba(255, 200, 0, 0.4)');
      coronaGrad.addColorStop(0.5, 'rgba(255, 100, 0, 0.1)');
      coronaGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = coronaGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius * 4, 0, Math.PI * 2);
      ctx.fill();

      const sunBodyGrad = ctx.createRadialGradient(0, 0, sun.radius * 0.2, 0, 0, sun.radius);
      sunBodyGrad.addColorStop(0, '#FFF');
      sunBodyGrad.addColorStop(0.4, '#FDB813');
      sunBodyGrad.addColorStop(1, '#FF8C00');
      ctx.fillStyle = sunBodyGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius, 0, Math.PI * 2);
      ctx.fill();

      // 6. Planets & Moons
      planetsRuntime.current.forEach((rtPlanet, index) => {
        const config = PLANETS[index];
        if (config.type === 'star') return;
        if (config.type === 'comet' && !showComets) return;

        // Draw Trails
        if (rtPlanet.trail.length > 1) {
          ctx.beginPath();
          ctx.strokeStyle = config.color;
          ctx.lineWidth = Math.max(1, 1/scale);
          ctx.globalAlpha = config.type === 'comet' ? 0.6 : 0.3;
          rtPlanet.trail.forEach((point, i) => {
            if (i === 0) ctx.moveTo(point.x, point.y);
            else ctx.lineTo(point.x, point.y);
          });
          ctx.stroke();
          ctx.globalAlpha = 1.0;
        }

        const x = rtPlanet.visualX;
        const y = rtPlanet.visualY;
        const radius = config.radius * PLANET_SCALE_FACTOR;

        // Comet Tail Logic (Always points away from Sun)
        if (config.type === 'comet') {
           const distToSun = Math.sqrt(x*x + y*y);
           // Tail gets longer and brighter when closer to sun
           const maxTailLen = 100;
           const tailStrength = Math.min(1, 400 / distToSun); 

           if (tailStrength > 0.1) {
             const angleFromSun = Math.atan2(y, x);
             ctx.save();
             ctx.translate(x, y);
             ctx.rotate(angleFromSun);

             const tailGrad = ctx.createLinearGradient(0, 0, maxTailLen * tailStrength, 0);
             tailGrad.addColorStop(0, 'rgba(200, 230, 255, 0.8)');
             tailGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');

             ctx.fillStyle = tailGrad;
             ctx.beginPath();
             ctx.moveTo(0, -radius);
             ctx.lineTo(maxTailLen * tailStrength, 0);
             ctx.lineTo(0, radius);
             ctx.fill();
             ctx.restore();
           }
        }

        ctx.save();
        ctx.translate(x, y);

        if (config.name === 'Bumi' || config.name === 'Venus') {
            const atmoGrad = ctx.createRadialGradient(0, 0, radius, 0, 0, radius * 1.3);
            atmoGrad.addColorStop(0, (config.colors[2] || config.color) + '88');
            atmoGrad.addColorStop(1, 'rgba(0,0,0,0)');
            ctx.fillStyle = atmoGrad;
            ctx.beginPath();
            ctx.arc(0, 0, radius * 1.3, 0, Math.PI * 2);
            ctx.fill();
        }

        // Fix: Removed unused surfGrad variable
        if (config.colors.length > 2) {
             const angle = Math.PI / 4;
             const planetCtx = ctx.createLinearGradient(
                 -radius * Math.cos(angle), -radius * Math.sin(angle),
                 radius * Math.cos(angle), radius * Math.sin(angle)
             );
             config.colors.forEach((col, idx) => {
                 planetCtx.addColorStop(idx / (config.colors.length - 1), col);
             });
             ctx.fillStyle = planetCtx;
        } else {
             ctx.fillStyle = config.color;
        }

        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();

        if (config.hasRing) {
             ctx.save();
             ctx.rotate(Math.PI / 6);
             ctx.beginPath();
             ctx.strokeStyle = '#CDBA96';
             ctx.lineWidth = radius * 0.8;
             ctx.globalAlpha = 0.7;
             ctx.ellipse(0, 0, radius * 2.2, radius * 0.6, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.beginPath();
             ctx.strokeStyle = '#000';
             ctx.lineWidth = radius * 0.1;
             ctx.globalAlpha = 0.5;
             ctx.ellipse(0, 0, radius * 1.8, radius * 0.5, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.restore();
        }

        // Shadow Logic
        const angleToSun = Math.atan2(-y, -x);
        ctx.rotate(angleToSun);

        ctx.beginPath();
        ctx.fillStyle = 'rgba(0,0,0,0.75)';
        ctx.arc(0, 0, radius, Math.PI / 2, -Math.PI / 2); 
        ctx.fill();

        const shadowGrad = ctx.createLinearGradient(-radius/2, 0, radius/2, 0);
        shadowGrad.addColorStop(0, 'rgba(0,0,0,0.8)');
        shadowGrad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = shadowGrad;
        ctx.fillRect(-radius/2, -radius, radius, radius*2);

        ctx.restore();

        if (config.moons && rtPlanet.moons && scale > 0.15) {
          config.moons.forEach((moon, mIndex) => {
            const mAngle = rtPlanet.moons[mIndex].angle;
            const mx = x + Math.cos(mAngle) * moon.distance;
            const my = y + Math.sin(mAngle) * moon.distance;

            ctx.fillStyle = moon.color;
            ctx.beginPath();
            ctx.arc(mx, my, moon.radius, 0, Math.PI * 2);
            ctx.fill();

            const moonAngleToSun = Math.atan2(-my, -mx);
            ctx.save();
            ctx.translate(mx, my);
            ctx.rotate(moonAngleToSun);
            ctx.fillStyle = 'rgba(0,0,0,0.8)';
            ctx.beginPath();
            ctx.arc(0, 0, moon.radius, Math.PI/2, -Math.PI/2);
            ctx.fill();
            ctx.restore();

            if (selectedPlanet?.name === moon.name || hoveredPlanet?.name === moon.name) {
                ctx.strokeStyle = 'white';
                ctx.lineWidth = 1 / scale;
                ctx.beginPath();
                ctx.arc(mx, my, moon.radius + (2/scale), 0, Math.PI * 2);
                ctx.stroke();
            }
          });
        }

        if (selectedPlanet?.name === config.name || hoveredPlanet?.name === config.name) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 2 / scale;
          ctx.beginPath();
          ctx.arc(x, y, radius + (4/scale), 0, Math.PI * 2);
          ctx.stroke();
        }

        if (scale < 0.25 || selectedPlanet?.name === config.name) {
          ctx.fillStyle = '#EEE';
          ctx.font = `bold ${12/scale}px "Segoe UI", sans-serif`;
          ctx.textAlign = 'center';
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 4;
          ctx.fillText(config.name, x, y - (radius + 12/scale));
          ctx.shadowBlur = 0;
        }
      });

      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animationFrameId);
  }, [stars, asteroids, isPlaying, following, selectedPlanet, hoveredPlanet, showHabitableZone, showComets]);

  const handleWheel = (e: React.WheelEvent) => {
    const scale = simulationState.current.scale;
    const zoomSensitivity = 0.001 * scale; 
    let newScale = scale - e.deltaY * zoomSensitivity;
    newScale = Math.max(0.01, Math.min(newScale, 5));
    simulationState.current.scale = newScale;
    setUiZoom(newScale);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    simulationState.current.isDragging = true;
    simulationState.current.lastMouseX = e.clientX;
    simulationState.current.lastMouseY = e.clientY;
    if (following) setFollowing(null);
  };

  const handleMouseUp = () => {
    simulationState.current.isDragging = false;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (simulationState.current.isDragging) {
      const dx = e.clientX - simulationState.current.lastMouseX;
      const dy = e.clientY - simulationState.current.lastMouseY;
      simulationState.current.offsetX += dx;
      simulationState.current.offsetY += dy;
      simulationState.current.lastMouseX = e.clientX;
      simulationState.current.lastMouseY = e.clientY;
      setHoveredPlanet(null);
      return;
    }

    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    const width = canvas.width; 
    const height = canvas.height;
    const cx = width / 2;
    const cy = height / 2;
    const { scale, offsetX, offsetY } = simulationState.current;

    let found: PlanetConfig | MoonConfig | null = null;

    for (let i = 0; i < planetsRuntime.current.length; i++) {
      const rtP = planetsRuntime.current[i];
      const config = PLANETS[i];

      if (config.type === 'comet' && !showComets) continue;

      let pX = rtP.visualX;
      let pY = rtP.visualY;
      if (config.type === 'star') { pX = 0; pY = 0; }

      const screenX = cx + offsetX + pX * scale;
      const screenY = cy + offsetY + pY * scale;

      // Check Moons first
      if (config.moons && rtP.moons && scale > 0.15) {
         for(let m=0; m<config.moons.length; m++) {
             const moon = config.moons[m];
             const rtMoon = rtP.moons[m];
             const mx = pX + Math.cos(rtMoon.angle) * moon.distance;
             const my = pY + Math.sin(rtMoon.angle) * moon.distance;

             const screenMX = cx + offsetX + mx * scale;
             const screenMY = cy + offsetY + my * scale;

             const mHitRadius = Math.max(moon.radius * scale, 6); 
             const mDist = Math.hypot(mouseX - screenMX, mouseY - screenMY);

             if (mDist < mHitRadius) {
                 // FIX: Use 'as const' to satisfy TypeScript strict literal types
                 found = { ...moon, type: 'moon' as const };
                 break;
             }
         }
      }

      if (found) break;

      const hitRadius = Math.max(config.radius * scale, 12);
      const dist = Math.hypot(mouseX - screenX, mouseY - screenY);

      if (dist < hitRadius) {
        found = config;
        break;
      }
    }

    setHoveredPlanet(found);
    if (found) {
      setCursorPos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleClick = () => {
    if (hoveredPlanet) {
      handleSelectPlanet(hoveredPlanet);
    }
  };

  const handleSelectPlanet = (p: PlanetConfig | MoonConfig) => {
    setSelectedPlanet(p);
    setFollowing(p.name);

    // Auto-zoom logic
    const r = p.radius;
    let targetZoom = 1.0;

    // Outer planets (Radius >= 10) get 1.0x
    if (r >= 10) {
        targetZoom = 1.0;
    } else {
        // Inner planets/moons get calculated zoom
        targetZoom = Math.min(Math.max(20 / r, 1.0), 3.5);
    }

    setUiZoom(targetZoom);
    simulationState.current.scale = targetZoom;
  };

  const handleSidePanelFollow = (name: string) => {
      if (following === name) {
          setFollowing(null);
      } else {
          // Find the planet/moon object to calculate correct zoom
          let target: PlanetConfig | MoonConfig | undefined = PLANETS.find(p => p.name === name);
          if (!target) {
              // Check moons
              PLANETS.forEach(p => {
                  if (p.moons) {
                      const m = p.moons.find(m => m.name === name);
                      if (m) target = m;
                  }
              });
          }

          setFollowing(name);

          if (target) {
              const r = target.radius;
              let targetZoom = 1.0;

              if (r >= 10) {
                  targetZoom = 1.0;
              } else {
                  targetZoom = Math.min(Math.max(20 / r, 1.0), 3.5);
              }

              setUiZoom(targetZoom);
              simulationState.current.scale = targetZoom;
          }
      }
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      <Controls 
        speed={uiSpeed} setSpeed={setUiSpeed} 
        zoom={uiZoom} setZoom={setUiZoom} 
        isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}
        date={simulationDate}
        onSelectPlanet={(p) => handleSelectPlanet(p)}
        following={following}
        showHabitableZone={showHabitableZone}
        setShowHabitableZone={setShowHabitableZone}
        showComets={showComets}
        setShowComets={setShowComets}
      />

      <canvas
        ref={canvasRef}
        className={`block w-full h-full ${simulationState.current.isDragging ? 'cursor-grabbing' : hoveredPlanet ? 'cursor-pointer' : 'cursor-default'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onMouseMove={handleMouseMove}
        onClick={handleClick}
      />

      {!selectedPlanet && (
        <Tooltip x={cursorPos.x} y={cursorPos.y} planet={hoveredPlanet} />
      )}

      <SidePanel 
        planet={selectedPlanet} 
        onClose={() => setSelectedPlanet(null)} 
        onFollow={handleSidePanelFollow}
        isFollowing={!!(selectedPlanet && following === selectedPlanet.name)}
      />
    </div>
  );
};

export default SolarSystem;

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { PLANETS, generateStars, generateAsteroids } from '../constants';
import { PlanetConfig, PlanetRuntimeState, MoonConfig } from '../types';
import { Tooltip } from './Tooltip';
import { Controls } from './Controls';
import { SidePanel } from './SidePanel';

// Scale Factors
const AU_PIXELS = 120; // Scale Distance
const PLANET_SCALE_FACTOR = 1; // Base scale for planet sizes

const SolarSystem: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [hoveredPlanet, setHoveredPlanet] = useState<PlanetConfig | MoonConfig | null>(null);
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetConfig | MoonConfig | null>(null); 
  const [following, setFollowing] = useState<string | null>(null); 

  const [cursorPos, setCursorPos] = useState({ x: 0, y: 0 });
  const [uiSpeed, setUiSpeed] = useState(1);
  const [uiZoom, setUiZoom] = useState(0.4); // Start zoomed out a bit more
  const [isPlaying, setIsPlaying] = useState(true);
  const [simulationDate, setSimulationDate] = useState(Date.now());

  // New Visualization States
  const [showHabitableZone, setShowHabitableZone] = useState(false);
  const [showComets, setShowComets] = useState(true);

  // Simulation State
  const simulationState = useRef({
    scale: 0.4,
    speedMultiplier: 1,
    offsetX: 0,
    offsetY: 0,
    isDragging: false,
    lastMouseX: 0,
    lastMouseY: 0,
  });

  // Touch State Refs
  const touchStartRef = useRef<{ x: number, y: number, time: number } | null>(null);
  const lastTouchRef = useRef<{ x: number, y: number } | null>(null);
  const lastPinchDistRef = useRef<number | null>(null);

  const planetsRuntime = useRef<PlanetRuntimeState[]>(
    PLANETS.map(p => ({
      name: p.name,
      angle: Math.random() * Math.PI * 2,
      visualX: 0,
      visualY: 0,
      trail: [],
      moons: p.moons ? p.moons.map(() => ({ angle: Math.random() * Math.PI * 2 })) : []
    }))
  );

  const stars = useMemo(() => generateStars(1000), []);
  const asteroids = useMemo(() => generateAsteroids(500), []);

  useEffect(() => { simulationState.current.speedMultiplier = uiSpeed; }, [uiSpeed]);
  useEffect(() => { simulationState.current.scale = uiZoom; }, [uiZoom]);

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); 
    if (!ctx) return;

    let animationFrameId: number;

    const render = () => {
      if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }

      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      const { scale, offsetX, offsetY, speedMultiplier } = simulationState.current;

      // --- PHYSICS UPDATE ---
      if (isPlaying) {
        setSimulationDate(d => d + (speedMultiplier * 86400 * 1000 * 0.1));

        planetsRuntime.current.forEach((rtPlanet, index) => {
          const config = PLANETS[index];
          // Physics for Planets, Dwarfs, and Comets
          if (config.type === 'planet' || config.type === 'dwarf' || config.type === 'comet') {

            // Variable speed based on Kepler's 2nd Law (faster near perihelion)
            // Calculate r (distance) for current angle to adjust speed
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const currentR = (a * (1 - e * e)) / (1 + e * Math.cos(rtPlanet.angle));
            const normalizedR = currentR / (a); 
            // Simplified viscosity: closer = faster.
            const keplerSpeed = config.speed * (1 / (normalizedR * normalizedR)); 

            rtPlanet.angle += (keplerSpeed * 0.002) * speedMultiplier;

            // ELLIPTICAL ORBIT CALCULATION
            const b = a * Math.sqrt(1 - e*e); // Semi-minor axis
            const c = a * e; // Distance from center to focus (Sun)

            // Current position relative to Ellipse Center
            let ex = a * Math.cos(rtPlanet.angle);
            let ey = b * Math.sin(rtPlanet.angle);

            // Shift so Sun (focus) is at (0,0)
            rtPlanet.visualX = ex - c; 
            rtPlanet.visualY = ey;

            // Trail Logic
            if (rtPlanet.trail.length > 80) rtPlanet.trail.shift();
            // Comets leave denser trails
            const trailFrequency = config.type === 'comet' ? 5 : 20;
            if (Math.floor(Date.now() / trailFrequency) % 2 === 0) {
                rtPlanet.trail.push({ x: rtPlanet.visualX, y: rtPlanet.visualY });
            }

            // Update Moons
            if (config.moons && rtPlanet.moons) {
              config.moons.forEach((moon, mIndex) => {
                rtPlanet.moons[mIndex].angle += (moon.speed * 0.02) * speedMultiplier;
              });
            }
          }
        });

        asteroids.forEach(ast => {
            ast.angle += (ast.speed * 0.002) * speedMultiplier;
        });
      }

      // --- CAMERA UPDATE ---
      let currentOffsetX = offsetX;
      let currentOffsetY = offsetY;

      if (following) {
        // Find planet or moon to follow
        let targetX = 0;
        let targetY = 0;
        let foundTarget = false;

        const targetPlanet = planetsRuntime.current.find(p => p.name === following);
        if (targetPlanet) {
            targetX = targetPlanet.visualX;
            targetY = targetPlanet.visualY;
            foundTarget = true;
        } else {
             // Check if it's a moon
             for(let i=0; i<PLANETS.length; i++) {
                 const pConfig = PLANETS[i];
                 const pRuntime = planetsRuntime.current[i];
                 if(pConfig.moons && pRuntime.moons) {
                     const mIndex = pConfig.moons.findIndex(m => m.name === following);
                     if(mIndex !== -1) {
                         const mConfig = pConfig.moons[mIndex];
                         const mRuntime = pRuntime.moons[mIndex];
                         targetX = pRuntime.visualX + Math.cos(mRuntime.angle) * mConfig.distance;
                         targetY = pRuntime.visualY + Math.sin(mRuntime.angle) * mConfig.distance;
                         foundTarget = true;
                         break;
                     }
                 }
             }
        }

        if (foundTarget) {
            simulationState.current.offsetX = -targetX;
            simulationState.current.offsetY = -targetY;
            currentOffsetX = -targetX;
            currentOffsetY = -targetY;
        }
      }

      // --- DRAWING ---

      // 1. Background (Space)
      ctx.fillStyle = '#020205'; 
      ctx.fillRect(0, 0, width, height);

      const nebulaGrad = ctx.createRadialGradient(width/2, height/2, width * 0.2, width/2, height/2, width * 1.5);
      nebulaGrad.addColorStop(0, '#0a0b14');
      nebulaGrad.addColorStop(1, '#000000');
      ctx.fillStyle = nebulaGrad;
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(cx + currentOffsetX, cy + currentOffsetY);
      ctx.scale(scale, scale);

      // 2. Stars
      const parallaxScale = Math.max(0.1, 1/scale);
      stars.forEach(star => {
        ctx.globalAlpha = star.opacity;
        ctx.fillStyle = star.color;
        ctx.beginPath();
        ctx.arc(star.x * parallaxScale, star.y * parallaxScale, star.size / scale, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 3. Asteroid Belt
      ctx.fillStyle = '#555';
      asteroids.forEach(ast => {
        const r = ast.distance * AU_PIXELS;
        const x = Math.cos(ast.angle) * r;
        const y = Math.sin(ast.angle) * r;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.arc(x, y, (ast.size / scale), 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 4. Orbit Lines & Habitable Zone

      // Habitable Zone (Goldilocks Zone)
      if (showHabitableZone) {
          const hzInner = 0.95 * AU_PIXELS;
          const hzOuter = 1.37 * AU_PIXELS;
          ctx.beginPath();
          ctx.arc(0, 0, hzInner, 0, Math.PI * 2);
          ctx.arc(0, 0, hzOuter, 0, Math.PI * 2, true); // Create ring
          ctx.fillStyle = 'rgba(0, 255, 100, 0.1)';
          ctx.fill();
          ctx.strokeStyle = 'rgba(0, 255, 100, 0.2)';
          ctx.lineWidth = 1 / scale;
          ctx.stroke();
      }

      ctx.lineWidth = Math.max(0.5, 0.5 / scale);

      planetsRuntime.current.forEach((_, i) => {
          const config = PLANETS[i];
          if (config.type === 'comet' && !showComets) return;

          if (config.type === 'planet' || config.type === 'dwarf' || config.type === 'comet') {
            const a = config.distance * AU_PIXELS;
            const e = config.eccentricity;
            const b = a * Math.sqrt(1 - e*e);
            const c = a * e;
            ctx.beginPath();
            ctx.strokeStyle = config.type === 'comet' ? 'rgba(255,255,255,0.1)' : (config.type === 'dwarf' ? '#555' : '#333');
            if (config.type !== 'planet') ctx.setLineDash([5 / scale, 5 / scale]);
            else ctx.setLineDash([]);

            ctx.ellipse(-c, 0, a, b, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);
          }
      });

      // 5. Sun
      const sun = PLANETS[0];
      const coronaGrad = ctx.createRadialGradient(0, 0, sun.radius, 0, 0, sun.radius * 4);
      coronaGrad.addColorStop(0, 'rgba(255, 200, 0, 0.4)');
      coronaGrad.addColorStop(0.5, 'rgba(255, 100, 0, 0.1)');
      coronaGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = coronaGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius * 4, 0, Math.PI * 2);
      ctx.fill();

      const sunBodyGrad = ctx.createRadialGradient(0, 0, sun.radius * 0.2, 0, 0, sun.radius);
      sunBodyGrad.addColorStop(0, '#FFF');
      sunBodyGrad.addColorStop(0.4, '#FDB813');
      sunBodyGrad.addColorStop(1, '#FF8C00');
      ctx.fillStyle = sunBodyGrad;
      ctx.beginPath();
      ctx.arc(0, 0, sun.radius, 0, Math.PI * 2);
      ctx.fill();

      // 6. Planets & Moons
      planetsRuntime.current.forEach((rtPlanet, index) => {
        const config = PLANETS[index];
        if (config.type === 'star') return;
        if (config.type === 'comet' && !showComets) return;

        // Draw Trails
        if (rtPlanet.trail.length > 1) {
          ctx.beginPath();
          ctx.strokeStyle = config.color;
          ctx.lineWidth = Math.max(1, 1/scale);
          ctx.globalAlpha = config.type === 'comet' ? 0.6 : 0.3;
          rtPlanet.trail.forEach((point, i) => {
            if (i === 0) ctx.moveTo(point.x, point.y);
            else ctx.lineTo(point.x, point.y);
          });
          ctx.stroke();
          ctx.globalAlpha = 1.0;
        }

        const x = rtPlanet.visualX;
        const y = rtPlanet.visualY;
        const radius = config.radius * PLANET_SCALE_FACTOR;

        // Comet Tail Logic (Always points away from Sun)
        if (config.type === 'comet') {
           const distToSun = Math.sqrt(x*x + y*y);
           const maxTailLen = 100;
           const tailStrength = Math.min(1, 400 / distToSun); 

           if (tailStrength > 0.1) {
             const angleFromSun = Math.atan2(y, x);
             ctx.save();
             ctx.translate(x, y);
             ctx.rotate(angleFromSun);

             const tailGrad = ctx.createLinearGradient(0, 0, maxTailLen * tailStrength, 0);
             tailGrad.addColorStop(0, 'rgba(200, 230, 255, 0.8)');
             tailGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');

             ctx.fillStyle = tailGrad;
             ctx.beginPath();
             ctx.moveTo(0, -radius);
             ctx.lineTo(maxTailLen * tailStrength, 0);
             ctx.lineTo(0, radius);
             ctx.fill();
             ctx.restore();
           }
        }

        ctx.save();
        ctx.translate(x, y);

        if (config.name === 'Bumi' || config.name === 'Venus') {
            const atmoGrad = ctx.createRadialGradient(0, 0, radius, 0, 0, radius * 1.3);
            atmoGrad.addColorStop(0, (config.colors[2] || config.color) + '88');
            atmoGrad.addColorStop(1, 'rgba(0,0,0,0)');
            ctx.fillStyle = atmoGrad;
            ctx.beginPath();
            ctx.arc(0, 0, radius * 1.3, 0, Math.PI * 2);
            ctx.fill();
        }

        if (config.colors.length > 2) {
             const angle = Math.PI / 4;
             const planetCtx = ctx.createLinearGradient(
                 -radius * Math.cos(angle), -radius * Math.sin(angle),
                 radius * Math.cos(angle), radius * Math.sin(angle)
             );
             config.colors.forEach((col, idx) => {
                 planetCtx.addColorStop(idx / (config.colors.length - 1), col);
             });
             ctx.fillStyle = planetCtx;
        } else {
             ctx.fillStyle = config.color;
        }

        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();

        if (config.hasRing) {
             ctx.save();
             ctx.rotate(Math.PI / 6);
             ctx.beginPath();
             ctx.strokeStyle = '#CDBA96';
             ctx.lineWidth = radius * 0.8;
             ctx.globalAlpha = 0.7;
             ctx.ellipse(0, 0, radius * 2.2, radius * 0.6, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.beginPath();
             ctx.strokeStyle = '#000';
             ctx.lineWidth = radius * 0.1;
             ctx.globalAlpha = 0.5;
             ctx.ellipse(0, 0, radius * 1.8, radius * 0.5, 0, 0, Math.PI * 2);
             ctx.stroke();

             ctx.restore();
        }

        // Shadow Logic
        const angleToSun = Math.atan2(-y, -x);
        ctx.rotate(angleToSun);

        ctx.beginPath();
        ctx.fillStyle = 'rgba(0,0,0,0.75)';
        ctx.arc(0, 0, radius, Math.PI / 2, -Math.PI / 2); 
        ctx.fill();

        const shadowGrad = ctx.createLinearGradient(-radius/2, 0, radius/2, 0);
        shadowGrad.addColorStop(0, 'rgba(0,0,0,0.8)');
        shadowGrad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = shadowGrad;
        ctx.fillRect(-radius/2, -radius, radius, radius*2);

        ctx.restore();

        if (config.moons && rtPlanet.moons && scale > 0.15) {
          config.moons.forEach((moon, mIndex) => {
            const mAngle = rtPlanet.moons[mIndex].angle;
            const mx = x + Math.cos(mAngle) * moon.distance;
            const my = y + Math.sin(mAngle) * moon.distance;

            ctx.fillStyle = moon.color;
            ctx.beginPath();
            ctx.arc(mx, my, moon.radius, 0, Math.PI * 2);
            ctx.fill();

            const moonAngleToSun = Math.atan2(-my, -mx);
            ctx.save();
            ctx.translate(mx, my);
            ctx.rotate(moonAngleToSun);
            ctx.fillStyle = 'rgba(0,0,0,0.8)';
            ctx.beginPath();
            ctx.arc(0, 0, moon.radius, Math.PI/2, -Math.PI/2);
            ctx.fill();
            ctx.restore();

            if (selectedPlanet?.name === moon.name || hoveredPlanet?.name === moon.name) {
                ctx.strokeStyle = 'white';
                ctx.lineWidth = 1 / scale;
                ctx.beginPath();
                ctx.arc(mx, my, moon.radius + (2/scale), 0, Math.PI * 2);
                ctx.stroke();
            }
          });
        }

        if (selectedPlanet?.name === config.name || hoveredPlanet?.name === config.name) {
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 2 / scale;
          ctx.beginPath();
          ctx.arc(x, y, radius + (4/scale), 0, Math.PI * 2);
          ctx.stroke();
        }

        if (scale < 0.25 || selectedPlanet?.name === config.name) {
          ctx.fillStyle = '#EEE';
          ctx.font = `bold ${12/scale}px "Segoe UI", sans-serif`;
          ctx.textAlign = 'center';
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 4;
          ctx.fillText(config.name, x, y - (radius + 12/scale));
          ctx.shadowBlur = 0;
        }
      });

      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animationFrameId);
  }, [stars, asteroids, isPlaying, following, selectedPlanet, hoveredPlanet, showHabitableZone, showComets]);

  // Universal Hit Detection (Mouse & Touch)
  const checkHit = (clientX: number, clientY: number): PlanetConfig | MoonConfig | null => {
      const canvas = canvasRef.current;
      if (!canvas) return null;

      const rect = canvas.getBoundingClientRect();
      const mouseX = clientX - rect.left;
      const mouseY = clientY - rect.top;
      const width = canvas.width; 
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;
      const { scale, offsetX, offsetY } = simulationState.current;

      for (let i = 0; i < planetsRuntime.current.length; i++) {
        const rtP = planetsRuntime.current[i];
        const config = PLANETS[i];

        if (config.type === 'comet' && !showComets) continue;

        let pX = rtP.visualX;
        let pY = rtP.visualY;
        if (config.type === 'star') { pX = 0; pY = 0; }

        const screenX = cx + offsetX + pX * scale;
        const screenY = cy + offsetY + pY * scale;

        // Check Moons
        if (config.moons && rtP.moons && scale > 0.15) {
          for(let m=0; m<config.moons.length; m++) {
              const moon = config.moons[m];
              const rtMoon = rtP.moons[m];
              const mx = pX + Math.cos(rtMoon.angle) * moon.distance;
              const my = pY + Math.sin(rtMoon.angle) * moon.distance;

              const screenMX = cx + offsetX + mx * scale;
              const screenMY = cy + offsetY + my * scale;

              const mHitRadius = Math.max(moon.radius * scale, 15); // Larger hit area for easier tapping
              const mDist = Math.hypot(mouseX - screenMX, mouseY - screenMY);

              if (mDist < mHitRadius) {
                  return { ...moon, type: 'moon' as const };
              }
          }
        }

        const hitRadius = Math.max(config.radius * scale, 20); // Larger hit area for easier tapping
        const dist = Math.hypot(mouseX - screenX, mouseY - screenY);

        if (dist < hitRadius) {
          return config;
        }
      }
      return null;
  };

  const handleWheel = (e: React.WheelEvent) => {
    const scale = simulationState.current.scale;
    const zoomSensitivity = 0.001 * scale; 
    let newScale = scale - e.deltaY * zoomSensitivity;
    newScale = Math.max(0.01, Math.min(newScale, 5));
    simulationState.current.scale = newScale;
    setUiZoom(newScale);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    simulationState.current.isDragging = true;
    simulationState.current.lastMouseX = e.clientX;
    simulationState.current.lastMouseY = e.clientY;
    if (following) setFollowing(null);
  };

  const handleMouseUp = () => {
    simulationState.current.isDragging = false;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (simulationState.current.isDragging) {
      const dx = e.clientX - simulationState.current.lastMouseX;
      const dy = e.clientY - simulationState.current.lastMouseY;
      simulationState.current.offsetX += dx;
      simulationState.current.offsetY += dy;
      simulationState.current.lastMouseX = e.clientX;
      simulationState.current.lastMouseY = e.clientY;
      setHoveredPlanet(null);
      return;
    }

    const found = checkHit(e.clientX, e.clientY);
    setHoveredPlanet(found);
    if (found) {
      setCursorPos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleClick = () => {
    if (hoveredPlanet) {
      handleSelectPlanet(hoveredPlanet);
    }
  };

  // --- TOUCH HANDLERS (MOBILE) ---
  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 1) {
        const t = e.touches[0];
        touchStartRef.current = { x: t.clientX, y: t.clientY, time: Date.now() };
        lastTouchRef.current = { x: t.clientX, y: t.clientY };
        simulationState.current.isDragging = true;
        if (following) setFollowing(null);
    } else if (e.touches.length === 2) {
        const t1 = e.touches[0];
        const t2 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
        lastPinchDistRef.current = dist;
        simulationState.current.isDragging = false; // Zooming
    }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      // Pan
      if (e.touches.length === 1 && simulationState.current.isDragging && lastTouchRef.current) {
          const t = e.touches[0];
          const dx = t.clientX - lastTouchRef.current.x;
          const dy = t.clientY - lastTouchRef.current.y;

          simulationState.current.offsetX += dx;
          simulationState.current.offsetY += dy;
          lastTouchRef.current = { x: t.clientX, y: t.clientY };
      } 
      // Pinch Zoom
      else if (e.touches.length === 2 && lastPinchDistRef.current !== null) {
          const t1 = e.touches[0];
          const t2 = e.touches[1];
          const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);

          if (lastPinchDistRef.current > 0) {
              const scaleFactor = dist / lastPinchDistRef.current;
              let newScale = simulationState.current.scale * scaleFactor;
              newScale = Math.max(0.01, Math.min(newScale, 5));

              simulationState.current.scale = newScale;
              setUiZoom(newScale);
          }
          lastPinchDistRef.current = dist;
      }
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
      // Tap Detection
      if (e.changedTouches.length > 0 && touchStartRef.current) {
          const t = e.changedTouches[0];
          const dx = t.clientX - touchStartRef.current.x;
          const dy = t.clientY - touchStartRef.current.y;
          const dt = Date.now() - touchStartRef.current.time;

          // If tap was short (<300ms) and didn't move much (<10px)
          if (Math.hypot(dx, dy) < 10 && dt < 300 && e.touches.length === 0) {
              const hit = checkHit(t.clientX, t.clientY);
              if (hit) {
                  handleSelectPlanet(hit);
              }
          }
      }

      if (e.touches.length === 0) {
          simulationState.current.isDragging = false;
          lastTouchRef.current = null;
          lastPinchDistRef.current = null;
      }
  };

  const handleSelectPlanet = (p: PlanetConfig | MoonConfig) => {
    setSelectedPlanet(p);
    setFollowing(p.name);

    // Auto-zoom logic
    const r = p.radius;
    let targetZoom = 1.0;

    if (r >= 10) {
        targetZoom = 1.0;
    } else {
        targetZoom = Math.min(Math.max(20 / r, 1.0), 3.5);
    }

    setUiZoom(targetZoom);
    simulationState.current.scale = targetZoom;
  };

  const handleSidePanelFollow = (name: string) => {
      if (following === name) {
          setFollowing(null);
      } else {
          let target: PlanetConfig | MoonConfig | undefined = PLANETS.find(p => p.name === name);
          if (!target) {
              PLANETS.forEach(p => {
                  if (p.moons) {
                      const m = p.moons.find(m => m.name === name);
                      if (m) target = m;
                  }
              });
          }

          setFollowing(name);

          if (target) {
              const r = target.radius;
              let targetZoom = 1.0;
              if (r >= 10) {
                  targetZoom = 1.0;
              } else {
                  targetZoom = Math.min(Math.max(20 / r, 1.0), 3.5);
              }

              setUiZoom(targetZoom);
              simulationState.current.scale = targetZoom;
          }
      }
  };

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      <Controls 
        speed={uiSpeed} setSpeed={setUiSpeed} 
        zoom={uiZoom} setZoom={setUiZoom} 
        isPlaying={isPlaying} togglePlay={() => setIsPlaying(!isPlaying)}
        date={simulationDate}
        onSelectPlanet={(p) => handleSelectPlanet(p)}
        following={following}
        showHabitableZone={showHabitableZone}
        setShowHabitableZone={setShowHabitableZone}
        showComets={showComets}
        setShowComets={setShowComets}
      />

      <canvas
        ref={canvasRef}
        className={`block w-full h-full touch-none ${simulationState.current.isDragging ? 'cursor-grabbing' : hoveredPlanet ? 'cursor-pointer' : 'cursor-default'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onMouseMove={handleMouseMove}
        onClick={handleClick}

        /* Mobile Touch Events */
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      />

      {!selectedPlanet && (
        <Tooltip x={cursorPos.x} y={cursorPos.y} planet={hoveredPlanet} />
      )}

      <SidePanel 
        planet={selectedPlanet} 
        onClose={() => setSelectedPlanet(null)} 
        onFollow={handleSidePanelFollow}
        isFollowing={!!(selectedPlanet && following === selectedPlanet.name)}
      />
    </div>
  );
};

export default SolarSystem;
